'use client'

import { confirmDialog } from '@/components/ui/confirm-dialog'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import Image from 'next/image'
import type { EverloopRegion } from '@/lib/data/regions'
import type { MapLabel } from '@/lib/data/map-labels'

interface RegionLocation {
  id: string
  name: string
  slug: string
  type: string
  description: string | null
  stability: number
  tags: string[]
  imageUrl: string | null
  x: number
  z: number
  createdAt: string
}

interface Props {
  region: EverloopRegion
  staticLabels: MapLabel[]
}

type DraftMap = Record<string, { x: number; z: number }>

const SIZE_COLOR: Record<string, string> = {
  city: '#f0d890',
  town: '#d4a84b',
  village: '#b0c090',
  landmark: '#c090e0',
  ruin: '#888',
  tavern: '#d08040',
  outpost: '#80b0d0',
}

const SIZE_DOT: Record<string, number> = {
  city: 12, town: 10, landmark: 9, tavern: 8, outpost: 8, village: 7, ruin: 7,
}

function getTypeColor(type: string): string {
  const colors: Record<string, string> = {
    location: '#d4a84b', character: '#6ec6ff', artifact: '#e066ff',
    faction: '#ff6b6b', creature: '#66ff9e', event: '#ffaa66', concept: '#66d9ff',
  }
  return colors[type] || '#d4a84b'
}

export default function MapMakerClient({ region, staticLabels }: Props) {
  // ---------------- Data ----------------
  const [labelDrafts, setLabelDrafts] = useState<DraftMap>({})
  const [entityDrafts, setEntityDrafts] = useState<DraftMap>({})
  const [entities, setEntities] = useState<RegionLocation[]>([])
  const [labelOverrides, setLabelOverrides] = useState<DraftMap>({})
  const [imageLoaded, setImageLoaded] = useState(false)
  const [saving, setSaving] = useState(false)
  const [saveMessage, setSaveMessage] = useState<string | null>(null)
  const [selected, setSelected] = useState<{ kind: 'label' | 'entity'; key: string } | null>(null)

  // ---------------- Pan / zoom ----------------
  const [pan, setPan] = useState({ x: 0, y: 0 })
  const [zoom, setZoom] = useState(1)
  const isPanning = useRef(false)
  const panStart = useRef({ x: 0, y: 0 })
  const panOrigin = useRef({ x: 0, y: 0 })
  const containerRef = useRef<HTMLDivElement>(null)
  const surfaceRef = useRef<HTMLDivElement>(null)

  // ---------------- Drag pin state ----------------
  const dragRef = useRef<
    | null
    | { kind: 'label' | 'entity'; key: string; moved: boolean }
  >(null)

  // ---------------- Load overrides + entities ----------------
  useEffect(() => {
    let cancelled = false
    async function load() {
      try {
        const [overridesRes, entitiesRes] = await Promise.all([
          fetch(`/api/map/regions/${region.id}/label-overrides`, { cache: 'no-store' }),
          fetch(`/api/map/regions/${region.id}/locations`, { cache: 'no-store' }),
        ])
        if (overridesRes.ok) {
          const data = await overridesRes.json()
          if (!cancelled) setLabelOverrides(data.overrides ?? {})
        }
        if (entitiesRes.ok) {
          const data = await entitiesRes.json()
          if (!cancelled) setEntities(data.locations ?? [])
        }
      } catch (err) {
        console.error('Map maker load failed:', err)
      }
    }
    load()
    return () => { cancelled = true }
  }, [region.id])

  // ---------------- Resolved positions ----------------
  const resolvedLabels = useMemo(() => {
    return staticLabels.map((l) => {
      const draft = labelDrafts[l.name]
      const override = labelOverrides[l.name]
      const pos = draft ?? override ?? { x: l.x, z: l.z }
      return { ...l, x: pos.x, z: pos.z, hasOverride: !!override, isDirty: !!draft }
    })
  }, [staticLabels, labelDrafts, labelOverrides])

  const resolvedEntities = useMemo(() => {
    // De-dupe: hide canon entities whose name is also a static label.
    const labelNames = new Set(staticLabels.map((l) => l.name.toLowerCase()))
    return entities
      .filter((e) => !labelNames.has(e.name.toLowerCase()))
      .map((e) => {
        const draft = entityDrafts[e.id]
        const pos = draft ?? { x: e.x, z: e.z }
        return { ...e, x: pos.x, z: pos.z, isDirty: !!draft }
      })
  }, [entities, entityDrafts, staticLabels])

  const dirtyCount =
    Object.keys(labelDrafts).length + Object.keys(entityDrafts).length

  // ---------------- Pan / zoom handlers ----------------
  const handleSurfacePointerDown = useCallback((e: React.PointerEvent) => {
    // Only pan when clicking the background (not a pin)
    if ((e.target as HTMLElement).dataset.pin) return
    if (e.button !== 0) return
    isPanning.current = true
    panStart.current = { x: e.clientX, y: e.clientY }
    panOrigin.current = { ...pan }
    ;(e.target as HTMLElement).setPointerCapture?.(e.pointerId)
  }, [pan])

  const handleSurfacePointerMove = useCallback((e: React.PointerEvent) => {
    if (isPanning.current) {
      const dx = e.clientX - panStart.current.x
      const dy = e.clientY - panStart.current.y
      setPan({ x: panOrigin.current.x + dx, y: panOrigin.current.y + dy })
      return
    }
  }, [])

  const handleSurfacePointerUp = useCallback(() => {
    isPanning.current = false
  }, [])

  const handleWheel = useCallback((e: React.WheelEvent) => {
    e.preventDefault()
    const container = containerRef.current
    if (!container) return
    const rect = container.getBoundingClientRect()
    const mouseX = e.clientX - rect.left
    const mouseY = e.clientY - rect.top
    const cx = rect.width / 2
    const cy = rect.height / 2
    setZoom((prev) => {
      const next = Math.min(8, Math.max(0.3, prev - e.deltaY * 0.002))
      const factor = 1 - next / prev
      setPan((p) => ({
        x: p.x + (mouseX - cx - p.x) * factor,
        y: p.y + (mouseY - cy - p.y) * factor,
      }))
      return next
    })
  }, [])

  const resetView = useCallback(() => {
    setPan({ x: 0, y: 0 })
    setZoom(1)
  }, [])

  // ---------------- Pin drag ----------------
  const beginPinDrag = useCallback(
    (e: React.PointerEvent, kind: 'label' | 'entity', key: string) => {
      e.stopPropagation()
      e.preventDefault()
      dragRef.current = { kind, key, moved: false }
      ;(e.target as HTMLElement).setPointerCapture?.(e.pointerId)
      setSelected({ kind, key })
    },
    []
  )

  const handlePinPointerMove = useCallback((e: React.PointerEvent) => {
    const drag = dragRef.current
    if (!drag) return
    const surface = surfaceRef.current
    if (!surface) return

    const rect = surface.getBoundingClientRect()
    // Convert client coords into the surface's percentage space
    const xPct = ((e.clientX - rect.left) / rect.width) * 100
    const zPct = ((e.clientY - rect.top) / rect.height) * 100
    const x = Math.max(0, Math.min(100, xPct))
    const z = Math.max(0, Math.min(100, zPct))

    drag.moved = true
    if (drag.kind === 'label') {
      setLabelDrafts((prev) => ({ ...prev, [drag.key]: { x, z } }))
    } else {
      setEntityDrafts((prev) => ({ ...prev, [drag.key]: { x, z } }))
    }
  }, [])

  const endPinDrag = useCallback((e: React.PointerEvent) => {
    if (dragRef.current) {
      ;(e.target as HTMLElement).releasePointerCapture?.(e.pointerId)
    }
    dragRef.current = null
  }, [])

  // ---------------- Save / discard ----------------
  const handleSave = useCallback(async () => {
    setSaving(true)
    setSaveMessage(null)
    try {
      const body = {
        regionId: region.id,
        labels: Object.entries(labelDrafts).map(([name, pos]) => ({ name, ...pos })),
        entities: Object.entries(entityDrafts).map(([id, pos]) => ({ id, ...pos })),
      }
      const res = await fetch('/api/admin/map-maker', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok) {
        setSaveMessage(`Save failed: ${data.error ?? res.status}`)
        return
      }
      // Bake drafts into committed overrides locally
      setLabelOverrides((prev) => ({ ...prev, ...labelDrafts }))
      setEntities((prev) =>
        prev.map((e) => entityDrafts[e.id]
          ? { ...e, x: entityDrafts[e.id].x, z: entityDrafts[e.id].z }
          : e
        )
      )
      setLabelDrafts({})
      setEntityDrafts({})
      setSaveMessage(`Saved ${data.savedLabels} label(s), ${data.savedEntities} entity position(s).`)
      setTimeout(() => setSaveMessage(null), 4000)
    } catch (err) {
      setSaveMessage(`Save failed: ${(err as Error).message}`)
    } finally {
      setSaving(false)
    }
  }, [labelDrafts, entityDrafts, region.id])

  const handleDiscard = useCallback(() => {
    setLabelDrafts({})
    setEntityDrafts({})
    setSaveMessage(null)
  }, [])

  const handleResetLabel = useCallback(async (name: string) => {
    if (!(await confirmDialog({ description: `Reset "${name}" to its default position?`, destructive: true }))) return
    setSaving(true)
    try {
      const res = await fetch(
        `/api/admin/map-maker?regionId=${encodeURIComponent(region.id)}&labelName=${encodeURIComponent(name)}`,
        { method: 'DELETE' }
      )
      if (!res.ok) {
        const data = await res.json().catch(() => ({}))
        setSaveMessage(`Reset failed: ${data.error ?? res.status}`)
        return
      }
      // Remove from local overrides and any pending draft
      setLabelOverrides((prev) => {
        const next = { ...prev }
        delete next[name]
        return next
      })
      setLabelDrafts((prev) => {
        const next = { ...prev }
        delete next[name]
        return next
      })
      setSaveMessage(`Reset "${name}" to default.`)
      setTimeout(() => setSaveMessage(null), 3000)
    } finally {
      setSaving(false)
    }
  }, [region.id])

  // ---------------- Render ----------------
  if (!region.mapImage) {
    return (
      <div className="p-12 text-center text-parchment-muted">
        This region has no map image yet — nothing to edit.
      </div>
    )
  }

  return (
    <div className="relative">
      {/* Toolbar */}
      <div className="px-6 py-3 border-b border-gold/10 bg-charcoal-900/40 flex items-center gap-3 flex-wrap sticky top-0 z-30 backdrop-blur-sm">
        <span className="text-xs text-parchment-muted">
          Drag any pin to reposition. Pan the map with the background.
        </span>
        <div className="flex-1" />
        {dirtyCount > 0 && (
          <span className="text-xs text-gold">
            {dirtyCount} unsaved change{dirtyCount === 1 ? '' : 's'}
          </span>
        )}
        {saveMessage && (
          <span className="text-xs text-parchment">{saveMessage}</span>
        )}
        <button
          onClick={handleDiscard}
          disabled={dirtyCount === 0 || saving}
          className="px-3 py-1.5 rounded-md border border-charcoal-700 text-xs text-parchment-muted hover:text-parchment hover:border-gold/30 transition-colors disabled:opacity-40"
        >
          Discard
        </button>
        <button
          onClick={handleSave}
          disabled={dirtyCount === 0 || saving}
          className="px-3 py-1.5 rounded-md text-xs font-medium border border-gold/40 bg-gold/20 text-gold hover:bg-gold/30 transition-colors disabled:opacity-40"
        >
          {saving ? 'Saving…' : 'Save Changes'}
        </button>
      </div>

      {/* Selected pin panel */}
      {selected && (() => {
        const labelMatch = resolvedLabels.find((l) => selected.kind === 'label' && l.name === selected.key)
        const entityMatch = resolvedEntities.find((e) => selected.kind === 'entity' && e.id === selected.key)
        const x = labelMatch?.x ?? entityMatch?.x ?? 0
        const z = labelMatch?.z ?? entityMatch?.z ?? 0
        const title = labelMatch?.name ?? entityMatch?.name ?? ''
        if (!title) return null
        return (
          <div className="absolute top-20 right-4 z-30 w-72 rounded-xl p-4 backdrop-blur-xl border border-gold/20 bg-charcoal-900/90">
            <div className="flex items-start justify-between gap-2 mb-2">
              <div>
                <div className="text-[10px] uppercase tracking-wider text-parchment-muted">
                  {selected.kind === 'label' ? `Static · ${labelMatch?.size}` : `Canon · ${entityMatch?.type}`}
                </div>
                <h3 className="text-sm font-serif font-bold text-gold">{title}</h3>
              </div>
              <button
                onClick={() => setSelected(null)}
                className="text-parchment-muted hover:text-parchment p-1"
                aria-label="Close"
              >
                ✕
              </button>
            </div>
            <div className="grid grid-cols-2 gap-2 text-xs">
              <div>
                <label className="text-[10px] text-parchment-muted">X (%)</label>
                <input
                  type="number"
                  step="0.1"
                  min={0}
                  max={100}
                  value={x.toFixed(2)}
                  onChange={(e) => {
                    const nx = Math.max(0, Math.min(100, parseFloat(e.target.value) || 0))
                    if (selected.kind === 'label') setLabelDrafts((p) => ({ ...p, [selected.key]: { x: nx, z } }))
                    else setEntityDrafts((p) => ({ ...p, [selected.key]: { x: nx, z } }))
                  }}
                  className="w-full mt-1 px-2 py-1 rounded bg-charcoal-700 border border-charcoal-600 text-parchment text-xs"
                />
              </div>
              <div>
                <label className="text-[10px] text-parchment-muted">Z (%)</label>
                <input
                  type="number"
                  step="0.1"
                  min={0}
                  max={100}
                  value={z.toFixed(2)}
                  onChange={(e) => {
                    const nz = Math.max(0, Math.min(100, parseFloat(e.target.value) || 0))
                    if (selected.kind === 'label') setLabelDrafts((p) => ({ ...p, [selected.key]: { x, z: nz } }))
                    else setEntityDrafts((p) => ({ ...p, [selected.key]: { x, z: nz } }))
                  }}
                  className="w-full mt-1 px-2 py-1 rounded bg-charcoal-700 border border-charcoal-600 text-parchment text-xs"
                />
              </div>
            </div>
            {selected.kind === 'label' && (
              <button
                onClick={() => handleResetLabel(selected.key)}
                className="mt-3 w-full text-[11px] text-parchment-muted hover:text-parchment py-1.5 rounded border border-charcoal-700 hover:border-gold/30 transition-colors"
              >
                Reset to code default
              </button>
            )}
          </div>
        )
      })()}

      {/* Map surface */}
      <div
        ref={containerRef}
        className="relative w-full h-[calc(100vh-160px)] overflow-hidden bg-charcoal"
        style={{ cursor: isPanning.current ? 'grabbing' : 'grab', touchAction: 'none' }}
        onPointerDown={handleSurfacePointerDown}
        onPointerMove={handleSurfacePointerMove}
        onPointerUp={handleSurfacePointerUp}
        onPointerCancel={handleSurfacePointerUp}
        onWheel={handleWheel}
      >
        {(zoom !== 1 || pan.x !== 0 || pan.y !== 0) && (
          <button
            onClick={(e) => { e.stopPropagation(); resetView() }}
            className="absolute bottom-4 right-4 z-30 px-3 py-2 rounded-lg text-xs font-medium backdrop-blur-xl border border-gold/30 bg-charcoal-900/90 text-gold"
          >
            ↻ Reset View
          </button>
        )}

        <div
          ref={surfaceRef}
          className="relative w-full h-full"
          style={{
            transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`,
            transformOrigin: 'center center',
            transition: isPanning.current ? 'none' : 'transform 0.15s ease-out',
          }}
          onPointerMove={handlePinPointerMove}
          onPointerUp={endPinDrag}
          onPointerCancel={endPinDrag}
        >
          <Image
            src={region.mapImage}
            alt={`Map of ${region.name}`}
            fill
            className="object-contain transition-opacity duration-700 pointer-events-none select-none"
            style={{ opacity: imageLoaded ? 1 : 0 }}
            onLoad={() => setImageLoaded(true)}
            priority
            sizes="100vw"
            draggable={false}
          />

          {/* Static labels */}
          {imageLoaded && resolvedLabels.map((label) => {
            const color = SIZE_COLOR[label.size] ?? '#d4a84b'
            const size = SIZE_DOT[label.size] ?? 8
            const isSelected = selected?.kind === 'label' && selected.key === label.name
            return (
              <div
                key={`label-${label.name}`}
                data-pin="label"
                className="absolute z-10"
                style={{
                  left: `${label.x}%`,
                  top: `${label.z}%`,
                  transform: 'translate(-50%, -50%)',
                  cursor: 'grab',
                  touchAction: 'none',
                }}
                onPointerDown={(e) => beginPinDrag(e, 'label', label.name)}
              >
                <div
                  data-pin="label"
                  className="rounded-full"
                  style={{
                    width: size + (isSelected ? 4 : 0),
                    height: size + (isSelected ? 4 : 0),
                    background: color,
                    boxShadow: `0 0 ${size}px ${color}80, 0 0 ${size * 2}px ${color}30`,
                    border: `2px solid ${isSelected ? '#fff' : color}`,
                    outline: label.isDirty ? '2px dashed #ffeb6c' : 'none',
                    outlineOffset: 2,
                  }}
                />
                <div
                  className="absolute left-1/2 -translate-x-1/2 whitespace-nowrap pointer-events-none"
                  style={{ top: size + 4 }}
                >
                  <span
                    className="text-[10px] font-serif font-bold px-1 py-0.5 rounded"
                    style={{
                      color,
                      textShadow: '0 0 6px rgba(0,0,0,0.9), 0 1px 3px rgba(0,0,0,0.8)',
                      background: isSelected ? 'rgba(5,10,15,0.8)' : 'transparent',
                    }}
                  >
                    {label.name}
                    {label.hasOverride && !label.isDirty && <span className="ml-1 opacity-60">·moved</span>}
                    {label.isDirty && <span className="ml-1 text-gold">·unsaved</span>}
                  </span>
                </div>
              </div>
            )
          })}

          {/* Canon entity pins */}
          {imageLoaded && resolvedEntities.map((loc) => {
            const color = getTypeColor(loc.type)
            const isSelected = selected?.kind === 'entity' && selected.key === loc.id
            return (
              <div
                key={`entity-${loc.id}`}
                data-pin="entity"
                className="absolute z-20"
                style={{
                  left: `${loc.x}%`,
                  top: `${loc.z}%`,
                  transform: 'translate(-50%, -100%)',
                  cursor: 'grab',
                  touchAction: 'none',
                }}
                onPointerDown={(e) => beginPinDrag(e, 'entity', loc.id)}
              >
                <div className="relative flex flex-col items-center pointer-events-none">
                  <div
                    data-pin="entity"
                    className="relative w-8 h-8 rounded-full flex items-center justify-center pointer-events-auto"
                    style={{
                      background: `linear-gradient(135deg, rgba(10,20,25,0.95), rgba(15,30,35,0.9))`,
                      border: `2px solid ${isSelected ? '#fff' : color}`,
                      boxShadow: `0 0 ${isSelected ? 16 : 8}px ${color}80`,
                      outline: loc.isDirty ? '2px dashed #ffeb6c' : 'none',
                      outlineOffset: 2,
                    }}
                  >
                    <span className="text-xs" style={{ color }}>◈</span>
                  </div>
                  <div className="w-0.5 h-2" style={{ background: `${color}80` }} />
                  <div className="w-1.5 h-1.5 rounded-full" style={{ background: color }} />
                  <div className="absolute -bottom-6 left-1/2 -translate-x-1/2 whitespace-nowrap">
                    <span
                      className="text-[10px] font-serif font-bold px-1.5 py-0.5 rounded"
                      style={{
                        color,
                        textShadow: '0 0 6px rgba(0,0,0,0.9)',
                        background: isSelected ? 'rgba(5,10,15,0.8)' : 'transparent',
                      }}
                    >
                      {loc.name}
                      {loc.isDirty && <span className="ml-1 text-gold">·unsaved</span>}
                    </span>
                  </div>
                </div>
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useTransition, useCallback } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import {
  freezeUser,
  unfreezeUser,
  deleteUser,
  resetUserPassword,
  toggleUserAdmin,
} from '@/lib/actions/admin'
import {
  Search,
  Loader2,
  Trash2,
  ShieldOff,
  KeyRound,
  UserCheck,
  RefreshCw,
  Copy,
  Check,
  Crown,
  CrownIcon,
  Wrench,
} from 'lucide-react'

interface UserRow {
  id: string
  email: string
  username: string | null
  display_name: string | null
  avatar_url: string | null
  role: string
  is_admin: boolean
  created_at: string
  last_sign_in_at: string | null
  is_banned: boolean
  banned_until: string | null
  email_confirmed_at: string | null
  has_profile: boolean
}

export function UsersClient() {
  const [users, setUsers] = useState<UserRow[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [statusFilter, setStatusFilter] = useState<'all' | 'active' | 'frozen'>('all')
  const [, startTransition] = useTransition()
  const [actioningId, setActioningId] = useState<string | null>(null)
  const [actionType, setActionType] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [successMsg, setSuccessMsg] = useState<string | null>(null)
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null)
  const [resetLink, setResetLink] = useState<string | null>(null)
  const [copiedLink, setCopiedLink] = useState(false)
  const [reconciling, setReconciling] = useState(false)

  const fetchUsers = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const res = await fetch('/api/admin/users')
      if (!res.ok) {
        const data = await res.json()
        throw new Error(data.error || 'Failed to fetch users')
      }
      const data = await res.json()
      setUsers(data.users)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load users')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    fetchUsers()
  }, [fetchUsers])

  const showSuccess = (msg: string) => {
    setSuccessMsg(msg)
    setTimeout(() => setSuccessMsg(null), 3000)
  }

  const handleFreeze = (userId: string) => {
    setActioningId(userId)
    setActionType('freeze')
    startTransition(async () => {
      const result = await freezeUser(userId)
      if (result.success) {
        showSuccess('User account frozen')
        await fetchUsers()
      } else {
        setError(result.error || 'Failed to freeze user')
      }
      setActioningId(null)
      setActionType(null)
    })
  }

  const handleUnfreeze = (userId: string) => {
    setActioningId(userId)
    setActionType('unfreeze')
    startTransition(async () => {
      const result = await unfreezeUser(userId)
      if (result.success) {
        showSuccess('User account unfrozen')
        await fetchUsers()
      } else {
        setError(result.error || 'Failed to unfreeze user')
      }
      setActioningId(null)
      setActionType(null)
    })
  }

  const handleDelete = (userId: string) => {
    if (confirmDelete !== userId) {
      setConfirmDelete(userId)
      return
    }
    setActioningId(userId)
    setActionType('delete')
    setConfirmDelete(null)
    startTransition(async () => {
      const result = await deleteUser(userId)
      if (result.success) {
        showSuccess('User account deleted')
        await fetchUsers()
      } else {
        setError(result.error || 'Failed to delete user')
      }
      setActioningId(null)
      setActionType(null)
    })
  }

  const handleResetPassword = (userId: string, email: string) => {
    setActioningId(userId)
    setActionType('reset')
    setResetLink(null)
    startTransition(async () => {
      const result = await resetUserPassword(userId, email)
      if (result.success) {
        if (result.resetLink) {
          setResetLink(result.resetLink)
        }
        showSuccess('Password reset link generated')
      } else {
        setError(result.error || 'Failed to generate reset link')
      }
      setActioningId(null)
      setActionType(null)
    })
  }

  const handleToggleAdmin = (userId: string, currentlyAdmin: boolean) => {
    setActioningId(userId)
    setActionType('admin')
    startTransition(async () => {
      const result = await toggleUserAdmin(userId, !currentlyAdmin)
      if (result.success) {
        showSuccess(currentlyAdmin ? 'Admin privileges removed' : 'Admin privileges granted')
        await fetchUsers()
      } else {
        setError(result.error || 'Failed to update admin status')
      }
      setActioningId(null)
      setActionType(null)
    })
  }

  const copyResetLink = async () => {
    if (resetLink) {
      await navigator.clipboard.writeText(resetLink)
      setCopiedLink(true)
      setTimeout(() => setCopiedLink(false), 2000)
    }
  }

  const handleReconcile = async () => {
    setReconciling(true)
    setError(null)
    try {
      const res = await fetch('/api/admin/users/reconcile', { method: 'POST' })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Reconcile failed')
      showSuccess(
        data.fixed > 0
          ? `Reconciled ${data.fixed} orphan profile${data.fixed === 1 ? '' : 's'}`
          : 'No orphan profiles found',
      )
      await fetchUsers()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Reconcile failed')
    } finally {
      setReconciling(false)
    }
  }

  // Filter users
  const filtered = users.filter(u => {
    const matchesSearch =
      !searchQuery ||
      u.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
      u.username?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      u.display_name?.toLowerCase().includes(searchQuery.toLowerCase())

    const matchesStatus =
      statusFilter === 'all' ||
      (statusFilter === 'active' && !u.is_banned) ||
      (statusFilter === 'frozen' && u.is_banned)

    return matchesSearch && matchesStatus
  })

  const stats = {
    total: users.length,
    active: users.filter(u => !u.is_banned).length,
    frozen: users.filter(u => u.is_banned).length,
    admins: users.filter(u => u.is_admin).length,
    orphans: users.filter(u => !u.has_profile).length,
  }

  const formatDate = (d: string | null) => {
    if (!d) return '—'
    return new Date(d).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    })
  }

  const relativeTime = (d: string | null) => {
    if (!d) return 'Never'
    const now = Date.now()
    const then = new Date(d).getTime()
    const diff = now - then
    const mins = Math.floor(diff / 60000)
    if (mins < 1) return 'Just now'
    if (mins < 60) return `${mins}m ago`
    const hours = Math.floor(mins / 60)
    if (hours < 24) return `${hours}h ago`
    const days = Math.floor(hours / 24)
    if (days < 30) return `${days}d ago`
    const months = Math.floor(days / 30)
    return `${months}mo ago`
  }

  return (
    <div className="max-w-7xl mx-auto px-6 py-8">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-serif text-parchment mb-2">User Management</h1>
        <p className="text-parchment-muted text-sm">
          View and manage all user accounts. All new signups are auto-approved.
        </p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-4 gap-4 mb-8">
        {[
          { label: 'Total Users', value: stats.total, color: 'text-parchment' },
          { label: 'Active', value: stats.active, color: 'text-emerald-400' },
          { label: 'Frozen', value: stats.frozen, color: 'text-red-400' },
          { label: 'Admins', value: stats.admins, color: 'text-gold' },
        ].map(s => (
          <div key={s.label} className="glass rounded-lg p-4 border border-gold/10">
            <p className="text-xs text-parchment-muted">{s.label}</p>
            <p className={`text-2xl font-bold ${s.color}`}>{loading ? '—' : s.value}</p>
          </div>
        ))}
      </div>

      {/* Alerts */}
      {error && (
        <div className="mb-4 p-3 rounded-lg bg-red-500/10 border border-red-500/30 text-red-300 text-sm flex items-center justify-between">
          <span>{error}</span>
          <button onClick={() => setError(null)} className="text-red-300 hover:text-red-200">✕</button>
        </div>
      )}
      {successMsg && (
        <div className="mb-4 p-3 rounded-lg bg-emerald-500/10 border border-emerald-500/30 text-emerald-300 text-sm">
          {successMsg}
        </div>
      )}
      {resetLink && (
        <div className="mb-4 p-3 rounded-lg bg-blue-500/10 border border-blue-500/30 text-blue-300 text-sm">
          <div className="flex items-center justify-between mb-1">
            <span className="font-medium">Password Reset Link Generated</span>
            <button onClick={() => setResetLink(null)} className="text-blue-300 hover:text-blue-200">✕</button>
          </div>
          <div className="flex items-center gap-2 mt-2">
            <code className="flex-1 text-xs bg-black/30 rounded px-2 py-1 overflow-x-auto break-all">{resetLink}</code>
            <Button size="sm" variant="outline" onClick={copyResetLink} className="shrink-0">
              {copiedLink ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
            </Button>
          </div>
        </div>
      )}

      {/* Search & Filters */}
      <div className="flex items-center gap-4 mb-6">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-parchment-muted" />
          <Input
            placeholder="Search by email, username, or display name..."
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            className="pl-10 bg-ink/50 border-gold/20 text-parchment"
          />
        </div>
        <div className="flex gap-1">
          {(['all', 'active', 'frozen'] as const).map(f => (
            <Button
              key={f}
              size="sm"
              variant={statusFilter === f ? 'default' : 'outline'}
              onClick={() => setStatusFilter(f)}
              className={statusFilter === f ? 'bg-gold/20 text-gold border-gold/30' : 'text-parchment-muted'}
            >
              {f.charAt(0).toUpperCase() + f.slice(1)}
            </Button>
          ))}
        </div>
        <Button
          size="sm"
          variant="outline"
          onClick={fetchUsers}
          disabled={loading}
          className="text-parchment-muted"
        >
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
        </Button>
        <Button
          size="sm"
          variant="outline"
          onClick={handleReconcile}
          disabled={reconciling}
          className="text-parchment-muted"
          title={
            stats.orphans > 0
              ? `Backfill ${stats.orphans} missing profile${stats.orphans === 1 ? '' : 's'}`
              : 'Backfill any auth users that are missing profiles'
          }
        >
          {reconciling ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : (
            <Wrench className="w-4 h-4" />
          )}
          <span className="ml-1 hidden sm:inline">
            Reconcile{stats.orphans > 0 ? ` (${stats.orphans})` : ''}
          </span>
        </Button>
      </div>

      {/* Table */}
      {loading ? (
        <div className="flex items-center justify-center py-20 text-parchment-muted">
          <Loader2 className="w-6 h-6 animate-spin mr-2" />
          Loading users...
        </div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-20 text-parchment-muted">
          {searchQuery || statusFilter !== 'all' ? 'No users match your filters.' : 'No users found.'}
        </div>
      ) : (
        <div className="glass rounded-lg border border-gold/10 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-gold/10">
                  <th className="text-left p-4 text-xs text-parchment-muted font-medium uppercase tracking-wider">User</th>
                  <th className="text-left p-4 text-xs text-parchment-muted font-medium uppercase tracking-wider">Role</th>
                  <th className="text-left p-4 text-xs text-parchment-muted font-medium uppercase tracking-wider">Status</th>
                  <th className="text-left p-4 text-xs text-parchment-muted font-medium uppercase tracking-wider">Last Sign In</th>
                  <th className="text-left p-4 text-xs text-parchment-muted font-medium uppercase tracking-wider">Joined</th>
                  <th className="text-right p-4 text-xs text-parchment-muted font-medium uppercase tracking-wider">Actions</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map(user => {
                  const isActioning = actioningId === user.id
                  return (
                    <tr
                      key={user.id}
                      className="border-b border-gold/5 hover:bg-gold/5 transition-colors"
                    >
                      {/* User info */}
                      <td className="p-4">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-gold/10 flex items-center justify-center text-gold text-xs font-bold shrink-0 overflow-hidden">
                            {user.avatar_url ? (
                              // eslint-disable-next-line @next/next/no-img-element -- user-supplied avatar URL from arbitrary hosts
                              <img src={user.avatar_url} alt="" className="w-full h-full object-cover rounded-full" />
                            ) : (
                              (user.username?.[0] || user.email[0]).toUpperCase()
                            )}
                          </div>
                          <div className="min-w-0">
                            <div className="flex items-center gap-2">
                              <span className="text-parchment font-medium truncate">
                                {user.display_name || user.username || 'No profile'}
                              </span>
                              {user.is_admin && (
                                <Crown className="w-3.5 h-3.5 text-gold shrink-0" />
                              )}
                            </div>
                            <p className="text-xs text-parchment-muted truncate">{user.email}</p>
                            {user.username && (
                              <p className="text-xs text-parchment-muted/60">@{user.username}</p>
                            )}
                          </div>
                        </div>
                      </td>

                      {/* Role */}
                      <td className="p-4">
                        <Badge variant="outline" className="text-xs capitalize border-gold/20 text-parchment-muted">
                          {user.role}
                        </Badge>
                      </td>

                      {/* Status */}
                      <td className="p-4">
                        {user.is_banned ? (
                          <Badge className="bg-red-500/20 text-red-300 border border-red-500/30 text-xs">
                            Frozen
                          </Badge>
                        ) : !user.has_profile ? (
                          <Badge className="bg-yellow-500/20 text-yellow-300 border border-yellow-500/30 text-xs">
                            No Profile
                          </Badge>
                        ) : (
                          <Badge className="bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 text-xs">
                            Active
                          </Badge>
                        )}
                      </td>

                      {/* Last Sign In */}
                      <td className="p-4">
                        <span className="text-parchment-muted text-xs" title={formatDate(user.last_sign_in_at)}>
                          {relativeTime(user.last_sign_in_at)}
                        </span>
                      </td>

                      {/* Joined */}
                      <td className="p-4">
                        <span className="text-parchment-muted text-xs">
                          {formatDate(user.created_at)}
                        </span>
                      </td>

                      {/* Actions */}
                      <td className="p-4">
                        <div className="flex items-center justify-end gap-1">
                          {/* Reset Password */}
                          <button
                            onClick={() => handleResetPassword(user.id, user.email)}
                            disabled={isActioning}
                            className="p-1.5 rounded hover:bg-gold/10 text-parchment-muted hover:text-blue-300 transition-colors disabled:opacity-50"
                            title="Reset password"
                          >
                            {isActioning && actionType === 'reset' ? (
                              <Loader2 className="w-4 h-4 animate-spin" />
                            ) : (
                              <KeyRound className="w-4 h-4" />
                            )}
                          </button>

                          {/* Toggle Admin */}
                          <button
                            onClick={() => handleToggleAdmin(user.id, user.is_admin)}
                            disabled={isActioning}
                            className={`p-1.5 rounded hover:bg-gold/10 transition-colors disabled:opacity-50 ${
                              user.is_admin ? 'text-gold hover:text-gold/70' : 'text-parchment-muted hover:text-gold'
                            }`}
                            title={user.is_admin ? 'Remove admin' : 'Make admin'}
                          >
                            {isActioning && actionType === 'admin' ? (
                              <Loader2 className="w-4 h-4 animate-spin" />
                            ) : (
                              <CrownIcon className="w-4 h-4" />
                            )}
                          </button>

                          {/* Freeze / Unfreeze */}
                          {user.is_banned ? (
                            <button
                              onClick={() => handleUnfreeze(user.id)}
                              disabled={isActioning}
                              className="p-1.5 rounded hover:bg-gold/10 text-emerald-400 hover:text-emerald-300 transition-colors disabled:opacity-50"
                              title="Unfreeze account"
                            >
                              {isActioning && actionType === 'unfreeze' ? (
                                <Loader2 className="w-4 h-4 animate-spin" />
                              ) : (
                                <UserCheck className="w-4 h-4" />
                              )}
                            </button>
                          ) : (
                            <button
                              onClick={() => handleFreeze(user.id)}
                              disabled={isActioning}
                              className="p-1.5 rounded hover:bg-gold/10 text-parchment-muted hover:text-orange-300 transition-colors disabled:opacity-50"
                              title="Freeze account"
                            >
                              {isActioning && actionType === 'freeze' ? (
                                <Loader2 className="w-4 h-4 animate-spin" />
                              ) : (
                                <ShieldOff className="w-4 h-4" />
                              )}
                            </button>
                          )}

                          {/* Delete */}
                          <button
                            onClick={() => handleDelete(user.id)}
                            disabled={isActioning}
                            className={`p-1.5 rounded hover:bg-gold/10 transition-colors disabled:opacity-50 ${
                              confirmDelete === user.id
                                ? 'text-red-400 bg-red-500/10'
                                : 'text-parchment-muted hover:text-red-400'
                            }`}
                            title={confirmDelete === user.id ? 'Click again to confirm delete' : 'Delete user'}
                          >
                            {isActioning && actionType === 'delete' ? (
                              <Loader2 className="w-4 h-4 animate-spin" />
                            ) : (
                              <Trash2 className="w-4 h-4" />
                            )}
                          </button>
                        </div>
                        {confirmDelete === user.id && (
                          <div className="flex items-center justify-end gap-2 mt-1">
                            <span className="text-xs text-red-400">Confirm delete?</span>
                            <button
                              onClick={() => setConfirmDelete(null)}
                              className="text-xs text-parchment-muted hover:text-parchment"
                            >
                              Cancel
                            </button>
                          </div>
                        )}
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>

          {/* Footer */}
          <div className="px-4 py-3 border-t border-gold/10 text-xs text-parchment-muted">
            Showing {filtered.length} of {users.length} users
          </div>
        </div>
      )}
    </div>
  )
}

import { searchMagicItems } from '@/lib/open5e'
import Link from 'next/link'
import { Suspense } from 'react'
import { Sparkles } from 'lucide-react'

export const metadata = { title: 'Magic Items — Compendium' }
export const dynamic = 'force-dynamic'

const RARITIES = ['common', 'uncommon', 'rare', 'very-rare', 'legendary', 'artifact']

interface PageProps { searchParams: Promise<{ q?: string; rarity?: string }> }

export default async function MagicItemsPage({ searchParams }: PageProps) {
  const params = await searchParams
  const search = params.q?.trim() || undefined
  const rarity = params.rarity || undefined

  return (
    <div className="max-w-6xl mx-auto px-6 py-8">
      <header className="mb-6 flex items-center gap-3">
        <Sparkles className="w-7 h-7 text-cyan-300" />
        <div>
          <h1 className="text-3xl font-serif text-parchment">Magic Items</h1>
          <Link href="/library" className="text-xs text-parchment-muted hover:text-gold">← Library</Link>
        </div>
      </header>

      <form className="grid sm:grid-cols-3 gap-3 mb-6">
        <input name="q" defaultValue={search} placeholder="Search…" className="sm:col-span-2 bg-charcoal-950 border border-gold/15 rounded-md px-3 py-2 text-sm text-parchment placeholder:text-parchment-muted/60" />
        <select name="rarity" defaultValue={rarity ?? ''} className="bg-charcoal-950 border border-gold/15 rounded-md px-3 py-2 text-sm text-parchment capitalize">
          <option value="">All rarities</option>
          {RARITIES.map((r) => <option key={r} value={r}>{r.replace('-', ' ')}</option>)}
        </select>
        <button type="submit" className="sm:col-span-3 bg-gold/20 hover:bg-gold/30 border border-gold/30 text-gold py-2 rounded-md text-sm font-medium">Search</button>
      </form>

      <Suspense fallback={<p className="text-parchment-muted">Loading…</p>}>
        <Results search={search} rarity={rarity} />
      </Suspense>
    </div>
  )
}

async function Results({ search, rarity }: { search?: string; rarity?: string }) {
  try {
    const data = await searchMagicItems({ search, rarity, limit: 60 })
    if (data.results.length === 0) return <p className="text-parchment-muted text-center py-8">No magic items found.</p>
    return (
      <ul className="space-y-2">
        {data.results.map((it) => (
          <li key={it.key} className="rounded-md border border-gold/10 bg-teal-rich/20 p-3 hover:border-gold/30">
            <div className="flex items-center justify-between gap-3">
              <div>
                <h3 className="text-parchment font-serif">{it.name}</h3>
                <p className="text-xs text-parchment-muted capitalize">
                  {it.rarity?.name}
                  {it.requires_attunement && <span className="text-amber-400"> • requires attunement</span>}
                </p>
              </div>
            </div>
            {it.description && <p className="text-xs text-parchment-muted mt-2 line-clamp-3">{it.description}</p>}
          </li>
        ))}
      </ul>
    )
  } catch (e) {
    return <p className="text-red-400">Failed to load magic items: {(e as Error).message}</p>
  }
}

