function SoundboardPanel({ scene }: { scene: QuestScene | null }) {
  const audio = useAudioPlayer(0.6)
  const [currentAmbient, setCurrentAmbient] = useState<string | null>(null)

  const sceneMeta = (scene?.metadata as Record<string, unknown> | null | undefined) ?? {}
  const media = (sceneMeta.media as Record<string, unknown> | undefined) ?? {}
  const sceneAmbienceUrl = (media.ambience_url as string | undefined) ?? null
  const sceneSfxButtons = (Array.isArray(media.sfx_buttons) ? media.sfx_buttons : []) as { id?: string; label: string; url: string }[]
  const ambienceSuggestions = suggestAmbienceFor(scene?.mood)
  const sfxSuggestions = suggestSfxFor(scene?.mood)

  function playAmbient(url: string, label: string) {
    audio.playAmbience(url, { loop: true })
    setCurrentAmbient(label)
  }

  function stopAmbient() {
    audio.stopAmbience()
    setCurrentAmbient(null)
  }

  function fireSfx(url: string) {
    audio.playOneShot(url)
  }

  return (
    <div className="story-card p-0 overflow-hidden">
      <div className="px-4 py-3 border-b border-gold/15 flex items-center justify-between bg-teal-rich/30">
        <div className="flex items-center gap-2">
          <Volume2 className="w-4 h-4 text-gold" />
          <span className="text-sm font-serif text-parchment">Soundboard</span>
        </div>
        {currentAmbient && (
          <button
            onClick={stopAmbient}
            className="text-[10px] text-parchment-muted hover:text-red-300 flex items-center gap-1"
          >
            <X className="w-3 h-3" /> Stop
          </button>
        )}
      </div>

      <div className="p-3 space-y-3">
        {/* Ambience now-playing */}
        <div className="rounded border border-gold/15 bg-teal-rich/40 p-2">
          <div className="flex items-center gap-2 mb-1.5">
            <Music className="w-3 h-3 text-gold" />
            <span className="text-[10px] uppercase tracking-wider text-parchment-muted">Ambience</span>
            <span className="text-xs text-parchment ml-auto truncate">
              {currentAmbient ?? 'silent'}
            </span>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={stopAmbient}
              disabled={!audio.ambience.playing}
              className="w-7 h-7 rounded-full bg-gold/20 hover:bg-gold/30 flex items-center justify-center disabled:opacity-30"
              title={audio.ambience.playing ? 'Stop ambience' : 'No ambience playing'}
            >
              {audio.ambience.playing ? <Pause className="w-3 h-3 text-parchment" /> : <Play className="w-3 h-3 text-parchment" />}
            </button>
            <input
              type="range"
              min={0}
              max={1}
              step={0.05}
              value={audio.masterVolume}
              onChange={e => audio.setMasterVolume(parseFloat(e.target.value))}
              className="flex-1 accent-gold"
            />
            <span className="text-[10px] text-parchment-muted w-8 text-right">
              {Math.round(audio.masterVolume * 100)}%
            </span>
          </div>
        </div>

        {/* Ambience options */}
        <div>
          <div className="text-[10px] uppercase tracking-wider text-parchment-muted mb-1">
            Ambience Tracks
          </div>
          <div className="flex flex-wrap gap-1">
            {sceneAmbienceUrl && (
              <button
                onClick={() => playAmbient(sceneAmbienceUrl, 'Scene')}
                className="px-2 py-1 text-[10px] rounded bg-amber-500/15 border border-amber-500/30 text-amber-200 hover:bg-amber-500/25"
              >
                ★ Scene Default
              </button>
            )}
            {ambienceSuggestions.map(a => (
              <button
                key={a.id}
                onClick={() => playAmbient(a.url, a.title)}
                className="px-2 py-1 text-[10px] rounded bg-teal-rich/50 border border-gold/15 text-parchment-muted hover:text-parchment hover:border-gold/30"
              >
                {a.title}
              </button>
            ))}
            {ambienceSuggestions.length === 0 && !sceneAmbienceUrl && (
              <span className="text-[10px] text-parchment-muted italic">No suggestions for this mood.</span>
            )}
          </div>
        </div>

        {/* SFX buttons */}
        <div>
          <div className="text-[10px] uppercase tracking-wider text-parchment-muted mb-1">
            SFX
          </div>
          <div className="grid grid-cols-2 gap-1">
            {sceneSfxButtons.map((b, i) => (
              <button
                key={b.id ?? i}
                onClick={() => fireSfx(b.url)}
                className="px-2 py-1.5 text-xs rounded bg-amber-500/15 border border-amber-500/30 text-amber-200 hover:bg-amber-500/25 truncate"
                title={b.label}
              >
                ★ {b.label}
              </button>
            ))}
            {sfxSuggestions.map(s => (
              <button
                key={s.id}
                onClick={() => fireSfx(s.url)}
                className="px-2 py-1.5 text-xs rounded bg-teal-rich/50 border border-gold/15 text-parchment-muted hover:text-parchment hover:border-gold/30 truncate"
                title={s.title}
              >
                {s.title}
              </button>
            ))}
          </div>
          {sceneSfxButtons.length === 0 && sfxSuggestions.length === 0 && (
            <p className="text-[10px] text-parchment-muted italic">No SFX configured for this mood.</p>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

/**
 * Projector View
 * --------------
 * Fullscreen, distraction-free image surface intended to be opened on a
 * second monitor / projector / casted display while the DM runs the
 * In-Person Dashboard on the primary screen.
 *
 * Receives image pushes from the dashboard via BroadcastChannel +
 * localStorage (no server round-trip — both windows are on the same machine).
 */

import { useEffect, useState, Suspense } from 'react'
import { useSearchParams } from 'next/navigation'

interface Payload {
  imageUrl: string | null
  caption: string | null
  sceneTitle: string | null
  mood: string | null
}

function ProjectorInner() {
  const search = useSearchParams()
  const sessionId = search.get('sessionId')
  const [payload, setPayload] = useState<Payload>({
    imageUrl: null, caption: null, sceneTitle: null, mood: null,
  })

  useEffect(() => {
    if (!sessionId) return
    const key = `everloop-projector-${sessionId}`

    // Hydrate from last-known
    try {
      const raw = localStorage.getItem(key)
      if (raw) setPayload(JSON.parse(raw))
    } catch { /* ignore */ }

    // Subscribe
    let bc: BroadcastChannel | null = null
    if (typeof BroadcastChannel !== 'undefined') {
      bc = new BroadcastChannel(key)
      bc.onmessage = (e) => setPayload(e.data as Payload)
    }
    // Fallback: storage events (cross-tab in same origin)
    const onStorage = (e: StorageEvent) => {
      if (e.key === key && e.newValue) {
        try { setPayload(JSON.parse(e.newValue)) } catch { /* ignore */ }
      }
    }
    window.addEventListener('storage', onStorage)
    return () => {
      bc?.close()
      window.removeEventListener('storage', onStorage)
    }
  }, [sessionId])

  if (!sessionId) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center text-parchment-muted text-sm">
        Missing sessionId — open this from the In-Person Dashboard.
      </div>
    )
  }

  return (
    <div className="fixed inset-0 bg-black flex flex-col items-center justify-center overflow-hidden">
      {payload.imageUrl ? (
        <>
          {/* eslint-disable-next-line @next/next/no-img-element -- dynamic projected image URL with unknown dimensions/host */}
          <img
            src={payload.imageUrl}
            alt={payload.caption ?? ''}
            className="max-w-full max-h-full object-contain"
          />
          {(payload.caption || payload.sceneTitle) && (
            <div className="absolute bottom-0 left-0 right-0 bg-linear-to-t from-black/90 via-black/60 to-transparent p-6 text-center">
              {payload.sceneTitle && (
                <div className="text-xs uppercase tracking-[0.3em] text-amber-200/80 mb-1">
                  {payload.sceneTitle}
                </div>
              )}
              {payload.caption && (
                <div className="text-2xl font-serif text-parchment">{payload.caption}</div>
              )}
            </div>
          )}
        </>
      ) : (
        <div className="text-center text-parchment-muted/40">
          <div className="text-6xl font-serif mb-2 opacity-30">●</div>
          <div className="text-sm">Awaiting the DM…</div>
        </div>
      )}
    </div>
  )
}

export default function ProjectorPage() {
  return (
    <Suspense fallback={<div className="min-h-screen bg-black" />}>
      <ProjectorInner />
    </Suspense>
  )
}

'use client'

import { useEffect, useState, useTransition } from 'react'
import { useRouter, useSearchParams, usePathname } from 'next/navigation'
import { Search, X, Loader2 } from 'lucide-react'

/**
 * Search box for the Roster. Updates the `q` URL param (debounced) while
 * preserving the active type/status filters so the server component can
 * filter the creator's entities by name, tagline, or description.
 */
export function RosterSearch({ initialQuery = '' }: { initialQuery?: string }) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const [value, setValue] = useState(initialQuery)
  const [isPending, startTransition] = useTransition()

  // Keep local state in sync if the URL changes externally (e.g. filter click).
  useEffect(() => {
    setValue(initialQuery)
  }, [initialQuery])

  useEffect(() => {
    const handle = setTimeout(() => {
      const current = searchParams.get('q') ?? ''
      if (value === current) return

      const params = new URLSearchParams(searchParams.toString())
      if (value.trim()) {
        params.set('q', value.trim())
      } else {
        params.delete('q')
      }
      const queryString = params.toString()
      startTransition(() => {
        router.replace(queryString ? `${pathname}?${queryString}` : pathname, {
          scroll: false,
        })
      })
    }, 250)

    return () => clearTimeout(handle)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value])

  return (
    <div className="relative w-full sm:max-w-sm">
      <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-parchment-muted" />
      <input
        type="text"
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder="Search your roster by name, tagline, or description…"
        aria-label="Search roster"
        className="w-full pl-10 pr-10 py-2 rounded-lg bg-teal-deep/50 border border-gold/20
                   text-parchment placeholder:text-parchment-muted/60
                   focus:border-gold/50 focus:ring-1 focus:ring-gold/20 focus:outline-hidden"
      />
      {isPending ? (
        <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-parchment-muted animate-spin" />
      ) : value ? (
        <button
          type="button"
          onClick={() => setValue('')}
          aria-label="Clear search"
          className="absolute right-3 top-1/2 -translate-y-1/2 text-parchment-muted hover:text-parchment transition-colors"
        >
          <X className="w-4 h-4" />
        </button>
      ) : null}
    </div>
  )
}

