'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { Check, Cloud, CloudOff, Loader2, AlertCircle } from 'lucide-react'
import { cn } from '@/lib/utils'

export type AutoSaveStatus = 'idle' | 'saving' | 'saved' | 'error' | 'offline'

interface AutoSaveIndicatorProps {
  status: AutoSaveStatus
  lastSaved?: Date | null
  errorMessage?: string
  className?: string
}

export function AutoSaveIndicator({ 
  status, 
  lastSaved, 
  errorMessage,
  className 
}: AutoSaveIndicatorProps) {
  const [timeAgo, setTimeAgo] = useState<string>('')

  // Update time ago display
  useEffect(() => {
    if (!lastSaved) return

    const updateTimeAgo = () => {
      const now = new Date()
      const diff = Math.floor((now.getTime() - lastSaved.getTime()) / 1000)

      if (diff < 5) {
        setTimeAgo('just now')
      } else if (diff < 60) {
        setTimeAgo(`${diff}s ago`)
      } else if (diff < 3600) {
        const mins = Math.floor(diff / 60)
        setTimeAgo(`${mins}m ago`)
      } else {
        const hours = Math.floor(diff / 3600)
        setTimeAgo(`${hours}h ago`)
      }
    }

    updateTimeAgo()
    const interval = setInterval(updateTimeAgo, 10000)

    return () => clearInterval(interval)
  }, [lastSaved])

  const getStatusConfig = () => {
    switch (status) {
      case 'saving':
        return {
          icon: <Loader2 className="w-3.5 h-3.5 animate-spin" />,
          text: 'Saving...',
          className: 'text-gold',
        }
      case 'saved':
        return {
          icon: <Check className="w-3.5 h-3.5" />,
          text: lastSaved ? `Saved ${timeAgo}` : 'Saved',
          className: 'text-emerald-500',
        }
      case 'error':
        return {
          icon: <AlertCircle className="w-3.5 h-3.5" />,
          text: errorMessage || 'Save failed',
          className: 'text-red-500',
        }
      case 'offline':
        return {
          icon: <CloudOff className="w-3.5 h-3.5" />,
          text: 'Offline',
          className: 'text-orange-500',
        }
      default:
        return {
          icon: <Cloud className="w-3.5 h-3.5" />,
          text: 'Ready',
          className: 'text-muted-foreground',
        }
    }
  }

  const config = getStatusConfig()

  return (
    <div 
      className={cn(
        'flex items-center gap-1.5 text-xs transition-all duration-300',
        config.className,
        className
      )}
      title={status === 'error' ? errorMessage : undefined}
    >
      {config.icon}
      <span className="hidden sm:inline">{config.text}</span>
    </div>
  )
}

// Hook for managing auto-save state
interface UseAutoSaveOptions {
  onSave: () => Promise<{ success: boolean; error?: string }>
  delay?: number // ms delay before saving
  enabled?: boolean
}

export function useAutoSave({ onSave, delay = 2000, enabled = true }: UseAutoSaveOptions) {
  const [status, setStatus] = useState<AutoSaveStatus>('idle')
  const [lastSaved, setLastSaved] = useState<Date | null>(null)
  const [errorMessage, setErrorMessage] = useState<string>()
  const [isOnline, setIsOnline] = useState(true)

  const saveTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  const pendingSaveRef = useRef(false)

  // Monitor online status
  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true)
      setStatus(prev => prev === 'offline' ? 'idle' : prev)
    }

    const handleOffline = () => {
      setIsOnline(false)
      setStatus('offline')
    }

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    // Check initial status
    setIsOnline(navigator.onLine)
    if (!navigator.onLine) setStatus('offline')

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  // Trigger save with debounce
  const triggerSave = useCallback(() => {
    if (!enabled || !isOnline) return

    // Clear existing timeout
    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current)
    }

    pendingSaveRef.current = true

    saveTimeoutRef.current = setTimeout(async () => {
      if (!pendingSaveRef.current) return

      setStatus('saving')
      setErrorMessage(undefined)

      try {
        const result = await onSave()

        if (result.success) {
          setStatus('saved')
          setLastSaved(new Date())
        } else {
          setStatus('error')
          setErrorMessage(result.error || 'Failed to save')
        }
      } catch (err) {
        setStatus('error')
        setErrorMessage(err instanceof Error ? err.message : 'Failed to save')
      }

      pendingSaveRef.current = false
    }, delay)
  }, [onSave, delay, enabled, isOnline])

  // Force immediate save
  const forceSave = useCallback(async () => {
    if (!isOnline) {
      setStatus('offline')
      return { success: false, error: 'Offline' }
    }

    // Clear pending save
    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current)
    }
    pendingSaveRef.current = false

    setStatus('saving')
    setErrorMessage(undefined)

    try {
      const result = await onSave()

      if (result.success) {
        setStatus('saved')
        setLastSaved(new Date())
      } else {
        setStatus('error')
        setErrorMessage(result.error || 'Failed to save')
      }

      return result
    } catch (err) {
      const error = err instanceof Error ? err.message : 'Failed to save'
      setStatus('error')
      setErrorMessage(error)
      return { success: false, error }
    }
  }, [onSave, isOnline])

  // Cleanup
  useEffect(() => {
    return () => {
      if (saveTimeoutRef.current) {
        clearTimeout(saveTimeoutRef.current)
      }
    }
  }, [])

  return {
    status,
    lastSaved,
    errorMessage,
    isOnline,
    triggerSave,
    forceSave,
    setStatus,
  }
}

'use client'

import { confirmDialog } from '@/components/ui/confirm-dialog'
import { useState, useEffect } from 'react'
import { 
  Plus, 
  GripVertical, 
  Loader2, 
  FileText, 
  CheckCircle, 
  PenLine, 
  AlertCircle,
  ChevronLeft,
  ChevronRight,
  Trash2
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Progress } from '@/components/ui/progress'
import { cn } from '@/lib/utils'
import { 
  getChapters, 
  createChapter, 
  deleteChapter,
  reorderChapters,
  type Chapter 
} from '@/lib/actions/chapters'

// Re-export Chapter type for consumers
export type { Chapter } from '@/lib/actions/chapters'

interface ChapterSidebarProps {
  storyId: string
  currentChapterId?: string | null
  onChapterSelect: (chapter: Chapter) => void
  onClose?: () => void
  onChapterCreate?: (chapter: Chapter) => void
  isCollapsed?: boolean
  onToggleCollapse?: () => void
}

const STATUS_CONFIG: Record<string, { icon: typeof FileText; color: string; label: string }> = {
  draft: { icon: FileText, color: 'text-muted-foreground', label: 'Draft' },
  in_progress: { icon: PenLine, color: 'text-blue-400', label: 'In Progress' },
  complete: { icon: CheckCircle, color: 'text-green-400', label: 'Complete' },
  revision: { icon: AlertCircle, color: 'text-orange-400', label: 'Revision' },
}

export function ChapterSidebar({
  storyId,
  currentChapterId,
  onChapterSelect,
  onChapterCreate,
  isCollapsed = false,
  onToggleCollapse,
}: ChapterSidebarProps) {
  const [chapters, setChapters] = useState<Chapter[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [isCreating, setIsCreating] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [draggedId, setDraggedId] = useState<string | null>(null)
  const [dragOverId, setDragOverId] = useState<string | null>(null)

  useEffect(() => {
    loadChapters()
  }, [storyId])

  const loadChapters = async () => {
    setIsLoading(true)
    setError(null)

    const result = await getChapters(storyId)

    if (result.success && result.chapters) {
      setChapters(result.chapters)
    } else {
      setError(result.error || 'Failed to load chapters')
    }

    setIsLoading(false)
  }

  const handleCreateChapter = async () => {
    setIsCreating(true)

    const result = await createChapter(storyId)

    if (result.success && result.chapter) {
      setChapters(prev => [...prev, result.chapter!])
      onChapterCreate?.(result.chapter)
      onChapterSelect(result.chapter)
    } else {
      setError(result.error || 'Failed to create chapter')
    }

    setIsCreating(false)
  }

  const handleDeleteChapter = async (chapterId: string, e: React.MouseEvent) => {
    e.stopPropagation()

    if (!(await confirmDialog({ description: 'Delete this chapter? This cannot be undone.', destructive: true }))) return

    const result = await deleteChapter(chapterId)

    if (result.success) {
      setChapters(prev => prev.filter(ch => ch.id !== chapterId))
    } else {
      setError(result.error || 'Failed to delete chapter')
    }
  }

  // Drag and drop handlers
  const handleDragStart = (e: React.DragEvent, chapterId: string) => {
    setDraggedId(chapterId)
    e.dataTransfer.effectAllowed = 'move'
  }

  const handleDragOver = (e: React.DragEvent, chapterId: string) => {
    e.preventDefault()
    if (chapterId !== draggedId) {
      setDragOverId(chapterId)
    }
  }

  const handleDragLeave = () => {
    setDragOverId(null)
  }

  const handleDrop = async (e: React.DragEvent, targetId: string) => {
    e.preventDefault()
    setDragOverId(null)

    if (!draggedId || draggedId === targetId) {
      setDraggedId(null)
      return
    }

    // Reorder locally first for instant feedback
    const draggedIndex = chapters.findIndex(ch => ch.id === draggedId)
    const targetIndex = chapters.findIndex(ch => ch.id === targetId)

    const newChapters = [...chapters]
    const [removed] = newChapters.splice(draggedIndex, 1)
    newChapters.splice(targetIndex, 0, removed)

    setChapters(newChapters)
    setDraggedId(null)

    // Persist to database
    const chapterIds = newChapters.map(ch => ch.id)
    const result = await reorderChapters(storyId, chapterIds)

    if (!result.success) {
      // Revert on error
      loadChapters()
      setError('Failed to reorder chapters')
    }
  }

  const handleDragEnd = () => {
    setDraggedId(null)
    setDragOverId(null)
  }

  // Calculate totals
  const totalWords = chapters.reduce((sum, ch) => sum + (ch.word_count || 0), 0)
  const totalTarget = chapters.reduce((sum, ch) => sum + (ch.word_target || 0), 0)
  const completedChapters = chapters.filter(ch => ch.status === 'complete').length

  if (isCollapsed) {
    return (
      <div className="w-12 border-r border-charcoal-700 bg-navy/30 flex flex-col items-center py-4">
        <button
          onClick={onToggleCollapse}
          className="p-2 rounded-md hover:bg-charcoal-700 text-muted-foreground hover:text-foreground transition-colors"
          title="Expand chapters"
        >
          <ChevronRight className="w-4 h-4" />
        </button>
        <div className="mt-4 text-xs text-muted-foreground writing-mode-vertical">
          {chapters.length} chapters
        </div>
      </div>
    )
  }

  return (
    <div className="w-64 border-r border-charcoal-700 bg-navy/30 flex flex-col h-full">
      {/* Header */}
      <div className="p-3 border-b border-charcoal-700 flex items-center justify-between">
        <h3 className="font-serif text-sm text-foreground">Chapters</h3>
        <div className="flex items-center gap-1">
          <Button
            variant="ghost"
            size="sm"
            onClick={handleCreateChapter}
            disabled={isCreating}
            className="h-7 w-7 p-0"
            title="Add chapter"
          >
            {isCreating ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Plus className="w-4 h-4" />
            )}
          </Button>
          {onToggleCollapse && (
            <button
              onClick={onToggleCollapse}
              className="p-1.5 rounded-md hover:bg-charcoal-700 text-muted-foreground hover:text-foreground transition-colors"
              title="Collapse"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>

      {/* Progress Summary */}
      {chapters.length > 0 && (
        <div className="p-3 border-b border-charcoal-700 space-y-2">
          <div className="flex justify-between text-xs text-muted-foreground">
            <span>{completedChapters}/{chapters.length} complete</span>
            <span>{totalWords.toLocaleString()} words</span>
          </div>
          {totalTarget > 0 && (
            <div className="space-y-1">
              <Progress 
                value={Math.min(100, (totalWords / totalTarget) * 100)} 
                className="h-1.5"
              />
              <div className="text-xs text-muted-foreground text-right">
                {Math.round((totalWords / totalTarget) * 100)}% of {totalTarget.toLocaleString()} target
              </div>
            </div>
          )}
        </div>
      )}

      {/* Chapter List */}
      <div className="flex-1 overflow-auto">
        {isLoading ? (
          <div className="flex items-center justify-center h-32">
            <Loader2 className="w-5 h-5 animate-spin text-gold" />
          </div>
        ) : error ? (
          <div className="p-4 text-center">
            <p className="text-sm text-destructive">{error}</p>
            <button 
              onClick={loadChapters}
              className="mt-2 text-sm text-gold hover:underline"
            >
              Try again
            </button>
          </div>
        ) : chapters.length === 0 ? (
          <div className="p-4 text-center">
            <p className="text-sm text-muted-foreground mb-3">
              No chapters yet. Start by adding your first chapter.
            </p>
            <Button
              variant="outline"
              size="sm"
              onClick={handleCreateChapter}
              disabled={isCreating}
              className="gap-2"
            >
              <Plus className="w-4 h-4" />
              Add Chapter
            </Button>
          </div>
        ) : (
          <div className="py-1">
            {chapters.map((chapter, index) => {
              const statusConfig = STATUS_CONFIG[chapter.status] || STATUS_CONFIG.draft
              const StatusIcon = statusConfig.icon
              const isActive = chapter.id === currentChapterId
              const isDragging = chapter.id === draggedId
              const isDragOver = chapter.id === dragOverId

              return (
                <div
                  key={chapter.id}
                  draggable
                  onDragStart={(e) => handleDragStart(e, chapter.id)}
                  onDragOver={(e) => handleDragOver(e, chapter.id)}
                  onDragLeave={handleDragLeave}
                  onDrop={(e) => handleDrop(e, chapter.id)}
                  onDragEnd={handleDragEnd}
                  onClick={() => onChapterSelect(chapter)}
                  className={cn(
                    'group flex items-start gap-2 px-3 py-2 cursor-pointer transition-colors',
                    isActive 
                      ? 'bg-gold/10 border-l-2 border-gold' 
                      : 'hover:bg-charcoal-700/50 border-l-2 border-transparent',
                    isDragging && 'opacity-50',
                    isDragOver && 'bg-gold/5 border-l-2 border-gold/50'
                  )}
                >
                  {/* Drag Handle */}
                  <div className="shrink-0 mt-0.5 cursor-grab active:cursor-grabbing opacity-0 group-hover:opacity-100 transition-opacity">
                    <GripVertical className="w-4 h-4 text-muted-foreground" />
                  </div>

                  {/* Chapter Info */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="text-xs text-muted-foreground">
                        {index + 1}.
                      </span>
                      <span className={cn(
                        'text-sm truncate',
                        isActive ? 'text-gold' : 'text-foreground'
                      )}>
                        {chapter.title}
                      </span>
                    </div>
                    <div className="flex items-center gap-2 mt-0.5">
                      <StatusIcon className={cn('w-3 h-3', statusConfig.color)} />
                      <span className="text-xs text-muted-foreground">
                        {chapter.word_count.toLocaleString()} words
                      </span>
                      {chapter.word_target > 0 && (
                        <span className="text-xs text-muted-foreground">
                          / {chapter.word_target.toLocaleString()}
                        </span>
                      )}
                    </div>
                  </div>

                  {/* Delete Button */}
                  <button
                    onClick={(e) => handleDeleteChapter(chapter.id, e)}
                    className="shrink-0 p-1 rounded opacity-0 group-hover:opacity-100 
                               hover:bg-destructive/20 text-muted-foreground hover:text-destructive 
                               transition-all"
                    title="Delete chapter"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              )
            })}
          </div>
        )}
      </div>

      {/* Footer */}
      {chapters.length > 0 && (
        <div className="p-3 border-t border-charcoal-700">
          <Button
            variant="ghost"
            size="sm"
            onClick={handleCreateChapter}
            disabled={isCreating}
            className="w-full gap-2 text-muted-foreground hover:text-foreground"
          >
            {isCreating ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Plus className="w-4 h-4" />
            )}
            Add Chapter
          </Button>
        </div>
      )}
    </div>
  )
}

'use client'

import { confirmDialog } from '@/components/ui/confirm-dialog'
import { useState, useEffect, useCallback } from 'react'
import { 
  Users, 
  X, 
  Plus, 
  Loader2, 
  UserPlus, 
  Crown,
  Eye,
  MessageSquare,
  Edit,
  UserCheck,
  Trash2,
  Check,
  ChevronDown
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import {
  getCollaborators,
  addCollaborator,
  updateCollaboratorRole,
  removeCollaborator,
  type StoryCollaborator,
  type CollaboratorRole,
} from '@/lib/actions/collaborators'
import { cn } from '@/lib/utils'

interface CollaboratorsModalProps {
  storyId: string
  storyTitle: string
  isOpen: boolean
  onClose: () => void
}

const ROLE_CONFIG: Record<CollaboratorRole | 'owner', {
  label: string
  description: string
  icon: typeof Eye
  color: string
}> = {
  owner: {
    label: 'Owner',
    description: 'Full control over the story',
    icon: Crown,
    color: 'text-gold',
  },
  co_author: {
    label: 'Co-Author',
    description: 'Can edit content and manage chapters',
    icon: UserCheck,
    color: 'text-green-400',
  },
  editor: {
    label: 'Editor',
    description: 'Can edit content',
    icon: Edit,
    color: 'text-blue-400',
  },
  commenter: {
    label: 'Commenter',
    description: 'Can add comments and suggestions',
    icon: MessageSquare,
    color: 'text-purple-400',
  },
  viewer: {
    label: 'Viewer',
    description: 'Can only read the story',
    icon: Eye,
    color: 'text-muted-foreground',
  },
}

const AVAILABLE_ROLES: CollaboratorRole[] = ['co_author', 'editor', 'commenter', 'viewer']

export function CollaboratorsModal({
  storyId,
  storyTitle,
  isOpen,
  onClose,
}: CollaboratorsModalProps) {
  const [collaborators, setCollaborators] = useState<StoryCollaborator[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Add collaborator state
  const [showAddForm, setShowAddForm] = useState(false)
  const [username, setUsername] = useState('')
  const [selectedRole, setSelectedRole] = useState<CollaboratorRole>('viewer')
  const [isAdding, setIsAdding] = useState(false)
  const [addError, setAddError] = useState<string | null>(null)

  // Role dropdown state
  const [openRoleDropdown, setOpenRoleDropdown] = useState<string | null>(null)

  const loadCollaborators = useCallback(async () => {
    setIsLoading(true)
    setError(null)

    const result = await getCollaborators(storyId)

    if (result.success && result.collaborators) {
      setCollaborators(result.collaborators)
    } else {
      setError(result.error || 'Failed to load collaborators')
    }

    setIsLoading(false)
  }, [storyId])

  useEffect(() => {
    if (isOpen) {
      loadCollaborators()
    }
  }, [isOpen, loadCollaborators])

  const handleAddCollaborator = async () => {
    if (!username.trim()) return

    setIsAdding(true)
    setAddError(null)

    const result = await addCollaborator(storyId, username.trim(), selectedRole)

    if (result.success && result.collaborator) {
      setCollaborators(prev => [...prev, result.collaborator!])
      setUsername('')
      setSelectedRole('viewer')
      setShowAddForm(false)
    } else {
      setAddError(result.error || 'Failed to add collaborator')
    }

    setIsAdding(false)
  }

  const handleUpdateRole = async (collaboratorId: string, newRole: CollaboratorRole) => {
    const result = await updateCollaboratorRole(collaboratorId, newRole)

    if (result.success && result.collaborator) {
      setCollaborators(prev => 
        prev.map(c => c.id === collaboratorId ? result.collaborator! : c)
      )
    }

    setOpenRoleDropdown(null)
  }

  const handleRemove = async (collaboratorId: string, userName: string) => {
    if (!(await confirmDialog({ description: `Remove ${userName} from this story?`, destructive: true }))) return

    const result = await removeCollaborator(collaboratorId)

    if (result.success) {
      setCollaborators(prev => prev.filter(c => c.id !== collaboratorId))
    }
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-xs"
        onClick={onClose}
      />

      {/* Modal */}
      <div className="relative w-full max-w-lg mx-4 bg-charcoal border border-charcoal-700 rounded-xl shadow-2xl">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-charcoal-700">
          <div className="flex items-center gap-3">
            <Users className="w-5 h-5 text-gold" />
            <div>
              <h2 className="text-lg font-serif">Collaborators</h2>
              <p className="text-sm text-muted-foreground truncate max-w-[300px]">
                {storyTitle}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-charcoal-700 rounded-lg transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 max-h-[60vh] overflow-y-auto">
          {/* Add Collaborator */}
          {!showAddForm ? (
            <Button
              variant="outline"
              onClick={() => setShowAddForm(true)}
              className="w-full mb-4 gap-2"
            >
              <UserPlus className="w-4 h-4" />
              Add Collaborator
            </Button>
          ) : (
            <div className="mb-6 p-4 rounded-lg bg-navy/30 border border-charcoal-700">
              <h3 className="text-sm font-medium mb-3">Add Collaborator</h3>

              <div className="space-y-3">
                <Input
                  placeholder="Enter username..."
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleAddCollaborator()}
                />

                {/* Role Selection */}
                <div className="grid grid-cols-2 gap-2">
                  {AVAILABLE_ROLES.map(role => {
                    const config = ROLE_CONFIG[role]
                    const Icon = config.icon
                    return (
                      <button
                        key={role}
                        onClick={() => setSelectedRole(role)}
                        className={cn(
                          'p-2 rounded-lg border text-left transition-colors',
                          selectedRole === role
                            ? 'border-gold bg-gold/10'
                            : 'border-charcoal-700 hover:border-charcoal-600'
                        )}
                      >
                        <div className="flex items-center gap-2">
                          <Icon className={cn('w-3.5 h-3.5', config.color)} />
                          <span className="text-sm">{config.label}</span>
                        </div>
                      </button>
                    )
                  })}
                </div>

                {addError && (
                  <p className="text-sm text-red-400">{addError}</p>
                )}

                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => {
                      setShowAddForm(false)
                      setUsername('')
                      setAddError(null)
                    }}
                    className="flex-1"
                  >
                    Cancel
                  </Button>
                  <Button
                    size="sm"
                    onClick={handleAddCollaborator}
                    disabled={!username.trim() || isAdding}
                    className="flex-1 gap-2"
                  >
                    {isAdding ? (
                      <Loader2 className="w-4 h-4 animate-spin" />
                    ) : (
                      <Plus className="w-4 h-4" />
                    )}
                    Add
                  </Button>
                </div>
              </div>
            </div>
          )}

          {/* Collaborators List */}
          {isLoading ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="w-6 h-6 animate-spin text-gold" />
            </div>
          ) : error ? (
            <div className="text-center py-8">
              <p className="text-red-400 mb-2">{error}</p>
              <Button variant="ghost" size="sm" onClick={loadCollaborators}>
                Try again
              </Button>
            </div>
          ) : collaborators.length === 0 ? (
            <div className="text-center py-8">
              <Users className="w-12 h-12 text-muted-foreground/50 mx-auto mb-3" />
              <p className="text-muted-foreground">No collaborators yet</p>
              <p className="text-sm text-muted-foreground/70 mt-1">
                Add collaborators to work on this story together
              </p>
            </div>
          ) : (
            <div className="space-y-2">
              {collaborators.map(collab => {
                const roleConfig = ROLE_CONFIG[collab.role]
                const RoleIcon = roleConfig.icon
                const isPending = !collab.accepted_at

                return (
                  <div
                    key={collab.id}
                    className={cn(
                      'flex items-center justify-between p-3 rounded-lg border',
                      isPending 
                        ? 'border-gold/30 bg-gold/5' 
                        : 'border-charcoal-700 bg-charcoal-800/30'
                    )}
                  >
                    <div className="flex items-center gap-3">
                      {/* Avatar */}
                      <div className="w-10 h-10 rounded-full bg-charcoal-700 flex items-center justify-center overflow-hidden">
                        {collab.user?.avatar_url ? (
                          // eslint-disable-next-line @next/next/no-img-element -- user-supplied avatar URL from arbitrary hosts
                          <img 
                            src={collab.user.avatar_url} 
                            alt="" 
                            className="w-full h-full object-cover"
                          />
                        ) : (
                          <span className="text-lg font-medium text-gold">
                            {collab.user?.username?.[0]?.toUpperCase() || '?'}
                          </span>
                        )}
                      </div>

                      <div>
                        <p className="font-medium">
                          {collab.user?.display_name || collab.user?.username || 'Unknown'}
                        </p>
                        <div className="flex items-center gap-2">
                          <span className="text-sm text-muted-foreground">
                            @{collab.user?.username}
                          </span>
                          {isPending && (
                            <Badge variant="outline" className="text-[10px] border-gold/50 text-gold">
                              Pending
                            </Badge>
                          )}
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center gap-2">
                      {/* Role Dropdown */}
                      <div className="relative">
                        <button
                          onClick={() => setOpenRoleDropdown(
                            openRoleDropdown === collab.id ? null : collab.id
                          )}
                          className={cn(
                            'flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-sm',
                            'hover:bg-charcoal-700 transition-colors',
                            roleConfig.color
                          )}
                        >
                          <RoleIcon className="w-3.5 h-3.5" />
                          <span>{roleConfig.label}</span>
                          <ChevronDown className="w-3 h-3 opacity-50" />
                        </button>

                        {openRoleDropdown === collab.id && (
                          <div className="absolute right-0 top-full mt-1 w-48 bg-charcoal border border-charcoal-700 rounded-lg shadow-xl z-10 py-1">
                            {AVAILABLE_ROLES.map(role => {
                              const config = ROLE_CONFIG[role]
                              const Icon = config.icon
                              const isSelected = role === collab.role

                              return (
                                <button
                                  key={role}
                                  onClick={() => handleUpdateRole(collab.id, role)}
                                  className={cn(
                                    'w-full flex items-center gap-2 px-3 py-2 text-left text-sm',
                                    'hover:bg-charcoal-700 transition-colors',
                                    isSelected && 'bg-charcoal-800'
                                  )}
                                >
                                  <Icon className={cn('w-4 h-4', config.color)} />
                                  <div className="flex-1">
                                    <p className={config.color}>{config.label}</p>
                                    <p className="text-xs text-muted-foreground">
                                      {config.description}
                                    </p>
                                  </div>
                                  {isSelected && (
                                    <Check className="w-4 h-4 text-gold" />
                                  )}
                                </button>
                              )
                            })}
                          </div>
                        )}
                      </div>

                      {/* Remove Button */}
                      <button
                        onClick={() => handleRemove(
                          collab.id, 
                          collab.user?.display_name || collab.user?.username || 'this user'
                        )}
                        className="p-1.5 text-muted-foreground hover:text-red-400 hover:bg-red-500/10 rounded transition-colors"
                        title="Remove collaborator"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                )
              })}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-charcoal-700">
          <p className="text-xs text-muted-foreground text-center">
            Collaborators can access this story based on their role permissions
          </p>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { 
  MessageSquare, 
  Lightbulb, 
  HelpCircle, 
  AlertTriangle,
  CheckCircle,
  Filter,
  X,
  ChevronDown,
  ChevronRight,
  Loader2
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { cn } from '@/lib/utils'
import { 
  getStoryComments, 
  getCommentCounts,
  resolveComment,
  type StoryComment,
  type CommentType 
} from '@/lib/actions/comments'

interface CommentsSidebarProps {
  storyId: string
  chapterId?: string | null
  isOpen: boolean
  onClose: () => void
  onCommentClick?: (comment: StoryComment) => void
}

const COMMENT_TYPE_CONFIG: Record<CommentType, { 
  icon: typeof MessageSquare
  color: string
  label: string 
}> = {
  note: { icon: MessageSquare, color: 'text-blue-400', label: 'Notes' },
  suggestion: { icon: Lightbulb, color: 'text-gold', label: 'Suggestions' },
  question: { icon: HelpCircle, color: 'text-purple-400', label: 'Questions' },
  issue: { icon: AlertTriangle, color: 'text-orange-400', label: 'Issues' },
}

type FilterType = 'all' | CommentType | 'unresolved'

export function CommentsSidebar({
  storyId,
  chapterId,
  isOpen,
  onClose,
  onCommentClick,
}: CommentsSidebarProps) {
  const [comments, setComments] = useState<StoryComment[]>([])
  const [counts, setCounts] = useState<{
    total: number
    unresolved: number
    notes: number
    suggestions: number
    questions: number
    issues: number
  } | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [filter, setFilter] = useState<FilterType>('all')
  const [showFilters, setShowFilters] = useState(false)
  const [expandedThreads, setExpandedThreads] = useState<Set<string>>(new Set())

  useEffect(() => {
    if (isOpen) {
      loadComments()
      loadCounts()
    }
  }, [isOpen, storyId, chapterId])

  const loadComments = async () => {
    setIsLoading(true)
    const result = await getStoryComments(storyId, { chapterId: chapterId || undefined })
    if (result.success && result.comments) {
      setComments(result.comments)
    }
    setIsLoading(false)
  }

  const loadCounts = async () => {
    const result = await getCommentCounts(storyId)
    if (result.success && result.counts) {
      setCounts(result.counts)
    }
  }

  const handleResolve = async (commentId: string, currentState: boolean) => {
    const result = await resolveComment(commentId, !currentState)
    if (result.success) {
      await loadComments()
      await loadCounts()
    }
  }

  const toggleThread = (threadId: string) => {
    const newExpanded = new Set(expandedThreads)
    if (newExpanded.has(threadId)) {
      newExpanded.delete(threadId)
    } else {
      newExpanded.add(threadId)
    }
    setExpandedThreads(newExpanded)
  }

  // Group comments by thread
  const groupedComments = comments.reduce<Record<string, StoryComment[]>>((acc, comment) => {
    const threadId = comment.thread_id || comment.id
    if (!acc[threadId]) {
      acc[threadId] = []
    }
    acc[threadId].push(comment)
    return acc
  }, {})

  // Get root comments (first in each thread)
  const rootComments = Object.values(groupedComments)
    .map(thread => thread.find(c => !c.parent_id) || thread[0])
    .filter(Boolean) as StoryComment[]

  // Apply filters
  const filteredComments = rootComments.filter(comment => {
    if (filter === 'all') return true
    if (filter === 'unresolved') return !comment.is_resolved
    return comment.comment_type === filter
  })

  if (!isOpen) return null

  return (
    <div className="fixed right-0 top-0 h-full w-80 bg-charcoal border-l border-charcoal-700 z-40 flex flex-col shadow-2xl">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-charcoal-700">
        <div className="flex items-center gap-2">
          <MessageSquare className="w-5 h-5 text-gold" />
          <h2 className="font-serif text-lg text-gold">Comments</h2>
          {counts && (
            <Badge variant="outline" className="text-xs">
              {counts.unresolved} open
            </Badge>
          )}
        </div>
        <Button 
          variant="ghost" 
          size="sm" 
          onClick={onClose}
          className="h-8 w-8 p-0"
        >
          <X className="w-4 h-4" />
        </Button>
      </div>

      {/* Filters */}
      <div className="p-3 border-b border-charcoal-700">
        <button
          type="button"
          onClick={() => setShowFilters(!showFilters)}
          className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors"
        >
          <Filter className="w-4 h-4" />
          <span>Filter: {filter === 'all' ? 'All' : filter === 'unresolved' ? 'Unresolved' : COMMENT_TYPE_CONFIG[filter as CommentType].label}</span>
          <ChevronDown className={cn('w-4 h-4 transition-transform', showFilters && 'rotate-180')} />
        </button>

        {showFilters && (
          <div className="mt-2 grid grid-cols-2 gap-1">
            <button
              type="button"
              onClick={() => { setFilter('all'); setShowFilters(false) }}
              className={cn(
                'px-2 py-1 text-xs rounded-md transition-colors',
                filter === 'all' ? 'bg-gold/20 text-gold' : 'text-muted-foreground hover:bg-charcoal-700'
              )}
            >
              All ({counts?.total || 0})
            </button>
            <button
              type="button"
              onClick={() => { setFilter('unresolved'); setShowFilters(false) }}
              className={cn(
                'px-2 py-1 text-xs rounded-md transition-colors',
                filter === 'unresolved' ? 'bg-gold/20 text-gold' : 'text-muted-foreground hover:bg-charcoal-700'
              )}
            >
              Unresolved ({counts?.unresolved || 0})
            </button>
            {(Object.keys(COMMENT_TYPE_CONFIG) as CommentType[]).map(type => {
              const config = COMMENT_TYPE_CONFIG[type]
              const count = counts ? counts[`${type}s` as keyof typeof counts] || 0 : 0
              return (
                <button
                  key={type}
                  type="button"
                  onClick={() => { setFilter(type); setShowFilters(false) }}
                  className={cn(
                    'px-2 py-1 text-xs rounded-md transition-colors flex items-center gap-1',
                    filter === type ? 'bg-gold/20 text-gold' : 'text-muted-foreground hover:bg-charcoal-700'
                  )}
                >
                  <config.icon className={cn('w-3 h-3', config.color)} />
                  {config.label} ({count})
                </button>
              )
            })}
          </div>
        )}
      </div>

      {/* Comments List */}
      <div className="flex-1 overflow-y-auto">
        {isLoading ? (
          <div className="flex items-center justify-center h-32">
            <Loader2 className="w-6 h-6 animate-spin text-gold" />
          </div>
        ) : filteredComments.length === 0 ? (
          <div className="p-6 text-center text-muted-foreground">
            <MessageSquare className="w-8 h-8 mx-auto mb-2 opacity-50" />
            <p className="text-sm">No comments yet</p>
            <p className="text-xs mt-1">Select text in the editor to add a comment</p>
          </div>
        ) : (
          <div className="divide-y divide-charcoal-700">
            {filteredComments.map(comment => {
              const config = COMMENT_TYPE_CONFIG[comment.comment_type]
              const Icon = config.icon
              const threadId = comment.thread_id || comment.id
              const threadComments = groupedComments[threadId] || []
              const hasReplies = threadComments.length > 1
              const isExpanded = expandedThreads.has(threadId)

              return (
                <div key={comment.id} className="group">
                  {/* Main Comment */}
                  <div 
                    className={cn(
                      'p-3 cursor-pointer hover:bg-charcoal-800/50 transition-colors',
                      comment.is_resolved && 'opacity-60'
                    )}
                    onClick={() => onCommentClick?.(comment)}
                  >
                    <div className="flex items-start gap-2">
                      <Icon className={cn('w-4 h-4 mt-0.5 shrink-0', config.color)} />
                      <div className="flex-1 min-w-0">
                        {/* Selected Text */}
                        {comment.selected_text && (
                          <p className="text-xs text-muted-foreground italic mb-1 line-clamp-1">
                            &ldquo;{comment.selected_text}&rdquo;
                          </p>
                        )}
                        {/* Comment Content */}
                        <p className="text-sm text-foreground/90 line-clamp-2">
                          {comment.content}
                        </p>
                        {/* Meta */}
                        <div className="flex items-center gap-2 mt-1">
                          <span className="text-xs text-muted-foreground">
                            {new Date(comment.created_at).toLocaleDateString()}
                          </span>
                          {hasReplies && (
                            <button
                              type="button"
                              onClick={(e) => { e.stopPropagation(); toggleThread(threadId) }}
                              className="text-xs text-gold hover:underline flex items-center gap-0.5"
                            >
                              {isExpanded ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
                              {threadComments.length - 1} {threadComments.length === 2 ? 'reply' : 'replies'}
                            </button>
                          )}
                        </div>
                      </div>
                      {/* Resolve Button */}
                      <button
                        type="button"
                        onClick={(e) => { e.stopPropagation(); handleResolve(comment.id, comment.is_resolved) }}
                        className={cn(
                          'p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity',
                          comment.is_resolved 
                            ? 'text-green-400 hover:bg-green-400/10' 
                            : 'text-muted-foreground hover:bg-charcoal-700'
                        )}
                        title={comment.is_resolved ? 'Unresolve' : 'Resolve'}
                      >
                        <CheckCircle className="w-4 h-4" />
                      </button>
                    </div>
                  </div>

                  {/* Thread Replies */}
                  {hasReplies && isExpanded && (
                    <div className="bg-charcoal-800/30 border-l-2 border-charcoal-700 ml-6">
                      {threadComments
                        .filter(c => c.id !== comment.id)
                        .map(reply => (
                          <div 
                            key={reply.id}
                            className="p-3 border-t border-charcoal-700/50"
                          >
                            <p className="text-sm text-foreground/80">{reply.content}</p>
                            <span className="text-xs text-muted-foreground">
                              {new Date(reply.created_at).toLocaleDateString()}
                            </span>
                          </div>
                        ))}
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        )}
      </div>

      {/* Footer Stats */}
      {counts && counts.total > 0 && (
        <div className="p-3 border-t border-charcoal-700 bg-charcoal-800/50">
          <div className="flex justify-between text-xs text-muted-foreground">
            <span>{counts.total} total</span>
            <span className="text-green-400">{counts.total - counts.unresolved} resolved</span>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Button } from '@/components/ui/button'
import { fetchRoster, type RosterEntity } from '@/lib/actions/roster'
import { weaveEntityIntoStory } from '@/lib/actions/weave'
import { X, User, Users, Loader2, Search, Globe, Lock, MapPin, Sparkles, Package, Shield, Brain, Calendar, Wand2 } from 'lucide-react'
import { Badge } from '@/components/ui/badge'

const typeIcons: Record<string, typeof User> = {
  character: User,
  location: MapPin,
  creature: Sparkles,
  artifact: Package,
  faction: Shield,
  concept: Brain,
  event: Calendar,
}

const typeColors: Record<string, string> = {
  character: 'text-amber-400',
  location: 'text-emerald-400',
  creature: 'text-purple-400',
  artifact: 'text-cyan-400',
  faction: 'text-red-400',
  concept: 'text-blue-400',
  event: 'text-orange-400',
}

interface RosterSidebarProps {
  isOpen: boolean
  onClose: () => void
  onInsertCharacter: (name: string, description: string) => void
  onWeaveEntity?: (paragraph: string) => void
  storyId?: string
  getContextBefore?: () => string
}

export function RosterSidebar({
  isOpen,
  onClose,
  onInsertCharacter,
  onWeaveEntity,
  storyId,
  getContextBefore,
}: RosterSidebarProps) {
  const [entities, setEntities] = useState<RosterEntity[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [isWeaving, setIsWeaving] = useState<string | null>(null) // Entity ID being woven
  const [error, setError] = useState<string | null>(null)
  const [searchQuery, setSearchQuery] = useState('')
  const [sourceFilter, setSourceFilter] = useState<'all' | 'global' | 'private'>('all')
  const [typeFilter, setTypeFilter] = useState<string>('all')

  useEffect(() => {
    if (isOpen && entities.length === 0) {
      loadRoster()
    }
  }, [isOpen])

  const loadRoster = async () => {
    setIsLoading(true)
    setError(null)

    try {
      const result = await fetchRoster()
      if (result.success && result.entities) {
        setEntities(result.entities)
      } else {
        setError(result.error || 'Failed to load roster')
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load roster')
    } finally {
      setIsLoading(false)
    }
  }

  const filteredEntities = entities.filter(entity => {
    const matchesSearch = entity.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         (entity.description?.toLowerCase().includes(searchQuery.toLowerCase()) ?? false)
    const matchesSource = sourceFilter === 'all' || 
                         (sourceFilter === 'global' && entity.isGlobal) ||
                         (sourceFilter === 'private' && !entity.isGlobal)
    const matchesType = typeFilter === 'all' || entity.type === typeFilter
    return matchesSearch && matchesSource && matchesType
  })

  // Get unique types for filter
  const availableTypes = [...new Set(entities.map(e => e.type))]

  const handleInsert = (entity: RosterEntity) => {
    const desc = entity.description 
      ? entity.description.slice(0, 150) + (entity.description.length > 150 ? '...' : '')
      : ''
    onInsertCharacter(entity.name, desc)
  }

  const handleWeave = async (entity: RosterEntity) => {
    if (!storyId || !getContextBefore || !onWeaveEntity) return

    setIsWeaving(entity.id)
    setError(null)

    try {
      const contextBefore = getContextBefore()

      if (!contextBefore || contextBefore.trim().length < 50) {
        setError('Write at least a paragraph first so the AI can match your style')
        setIsWeaving(null)
        return
      }

      const result = await weaveEntityIntoStory({
        entityId: entity.id,
        storyId,
        contextBefore,
      })

      if (result.success && result.paragraph) {
        onWeaveEntity(result.paragraph)
        onClose()
      } else {
        setError(result.error || 'Failed to weave entity')
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to weave entity')
    } finally {
      setIsWeaving(null)
    }
  }

  const canWeave = !!storyId && !!getContextBefore && !!onWeaveEntity

  if (!isOpen) return null

  return (
    <div className="fixed inset-y-0 right-0 z-50 flex">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/40"
        onClick={onClose}
      />

      {/* Sidebar */}
      <div className="relative ml-auto w-full max-w-md bg-charcoal border-l border-charcoal-700 shadow-2xl flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-charcoal-700">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-gold/10">
              <Users className="w-5 h-5 text-gold" />
            </div>
            <div>
              <h2 className="font-serif text-lg text-foreground">Roster</h2>
              <p className="text-sm text-muted-foreground">Insert entities into your story</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-md hover:bg-charcoal-700 text-muted-foreground hover:text-foreground transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Search & Filter */}
        <div className="p-4 border-b border-charcoal-700 space-y-3">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <input
              type="text"
              placeholder="Search entities..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 rounded-lg bg-navy/50 border border-charcoal-700
                         text-foreground placeholder:text-muted-foreground/50
                         focus:border-gold/50 focus:ring-1 focus:ring-gold/20 focus:outline-hidden"
            />
          </div>

          {/* Source Filter */}
          <div className="flex gap-2">
            <Button
              variant={sourceFilter === 'all' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setSourceFilter('all')}
              className={sourceFilter === 'all' ? 'bg-gold text-charcoal hover:bg-gold/90' : ''}
            >
              All
            </Button>
            <Button
              variant={sourceFilter === 'private' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setSourceFilter('private')}
              className={sourceFilter === 'private' ? 'bg-gold text-charcoal hover:bg-gold/90' : ''}
            >
              <Lock className="w-3 h-3 mr-1" />
              My Roster
            </Button>
            <Button
              variant={sourceFilter === 'global' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setSourceFilter('global')}
              className={sourceFilter === 'global' ? 'bg-gold text-charcoal hover:bg-gold/90' : ''}
            >
              <Globe className="w-3 h-3 mr-1" />
              Canon
            </Button>
          </div>

          {/* Type Filter */}
          <div className="flex gap-1 flex-wrap">
            <Button
              variant={typeFilter === 'all' ? 'default' : 'ghost'}
              size="sm"
              onClick={() => setTypeFilter('all')}
              className={`h-7 px-2 text-xs ${typeFilter === 'all' ? 'bg-gold/20 text-gold' : ''}`}
            >
              All Types
            </Button>
            {availableTypes.map((type) => {
              const Icon = typeIcons[type] || Sparkles
              return (
                <Button
                  key={type}
                  variant={typeFilter === type ? 'default' : 'ghost'}
                  size="sm"
                  onClick={() => setTypeFilter(type)}
                  className={`h-7 px-2 text-xs capitalize ${typeFilter === type ? 'bg-gold/20 text-gold' : ''}`}
                >
                  <Icon className={`w-3 h-3 mr-1 ${typeColors[type] || ''}`} />
                  {type}s
                </Button>
              )
            })}
          </div>
        </div>

        {/* Entity List */}
        <div className="flex-1 overflow-y-auto">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="w-6 h-6 animate-spin text-gold" />
            </div>
          ) : error ? (
            <div className="p-4">
              <div className="p-3 rounded-lg bg-destructive/10 border border-destructive/30 text-destructive text-sm">
                {error}
              </div>
              <Button onClick={loadRoster} variant="outline" size="sm" className="mt-3">
                Retry
              </Button>
            </div>
          ) : filteredEntities.length === 0 ? (
            <div className="p-8 text-center">
              <Sparkles className="w-12 h-12 mx-auto mb-3 text-muted-foreground/50" />
              <p className="text-muted-foreground">
                {searchQuery ? 'No entities match your search' : 'No entities available'}
              </p>
              {sourceFilter === 'private' && !searchQuery && (
                <p className="text-muted-foreground/70 text-sm mt-2">
                  Create entities in your Roster to see them here
                </p>
              )}
            </div>
          ) : (
            <div className="p-2">
              {filteredEntities.map((entity) => {
                const Icon = typeIcons[entity.type] || Sparkles
                return (
                  <button
                    key={entity.id}
                    onClick={() => handleInsert(entity)}
                    className="w-full p-3 rounded-lg text-left hover:bg-navy/50 transition-colors group"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <Icon className={`w-4 h-4 ${typeColors[entity.type] || 'text-gold'}`} />
                          <span className="font-medium text-foreground truncate">
                            {entity.name}
                          </span>
                          <Badge variant="outline" className="text-xs shrink-0">
                            {entity.isGlobal ? (
                              <><Globe className="w-3 h-3 mr-1" />Canon</>
                            ) : (
                              <><Lock className="w-3 h-3 mr-1" />{entity.status === 'draft' ? 'Draft' : 'Pending'}</>
                            )}
                          </Badge>
                        </div>
                        {entity.description && (
                          <p className="text-sm text-muted-foreground line-clamp-2">
                            {entity.description}
                          </p>
                        )}
                        {entity.tags.length > 0 && (
                          <div className="flex gap-1 mt-2 flex-wrap">
                            {entity.tags.slice(0, 3).map((tag) => (
                              <span 
                                key={tag}
                                className="px-1.5 py-0.5 text-xs rounded bg-charcoal-700 text-muted-foreground"
                              >
                                {tag}
                              </span>
                            ))}
                          </div>
                        )}

                        {/* Action buttons */}
                        <div className="flex gap-2 mt-3 pt-2 border-t border-charcoal-700/50">
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={(e) => {
                              e.stopPropagation()
                              handleInsert(entity)
                            }}
                            className="flex-1 h-7 text-xs"
                          >
                            Insert Name
                          </Button>
                          {canWeave && (
                            <Button
                              variant="default"
                              size="sm"
                              onClick={(e) => {
                                e.stopPropagation()
                                handleWeave(entity)
                              }}
                              disabled={isWeaving === entity.id}
                              className="flex-1 h-7 text-xs bg-gold text-charcoal hover:bg-gold/90 gap-1"
                            >
                              {isWeaving === entity.id ? (
                                <Loader2 className="w-3 h-3 animate-spin" />
                              ) : (
                                <Wand2 className="w-3 h-3" />
                              )}
                              Weave In
                            </Button>
                          )}
                        </div>
                      </div>
                    </div>
                  </button>
                )
              })}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-charcoal-700">
          <p className="text-xs text-muted-foreground text-center">
            {canWeave 
              ? 'Insert name or Weave to have AI introduce the entity into your story'
              : 'Click an entity to insert its name into your story'
            }
          </p>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Search, Loader2, User, MapPin, Sword, Calendar, Users, Lightbulb, Bug, ChevronRight } from 'lucide-react'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { cn } from '@/lib/utils'

interface CanonEntity {
  id: string
  name: string
  type: string
  description: string | null
  status: string
}

const ENTITY_TYPE_CONFIG: Record<string, { icon: typeof User; label: string; color: string }> = {
  character: { icon: User, label: 'Character', color: 'text-blue-400' },
  location: { icon: MapPin, label: 'Location', color: 'text-green-400' },
  artifact: { icon: Sword, label: 'Artifact', color: 'text-purple-400' },
  event: { icon: Calendar, label: 'Event', color: 'text-orange-400' },
  faction: { icon: Users, label: 'Faction', color: 'text-red-400' },
  concept: { icon: Lightbulb, label: 'Concept', color: 'text-cyan-400' },
  creature: { icon: Bug, label: 'Creature', color: 'text-yellow-400' },
}

export function LoreBrowserPanel() {
  const [entities, setEntities] = useState<CanonEntity[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedType, setSelectedType] = useState<string | null>(null)
  const [selectedEntity, setSelectedEntity] = useState<CanonEntity | null>(null)

  useEffect(() => {
    loadEntities()
  }, [])

  const loadEntities = async () => {
    setIsLoading(true)
    setError(null)

    try {
      const response = await fetch('/api/entities')
      if (!response.ok) throw new Error('Failed to load entities')
      const data = await response.json()
      setEntities(data.entities || [])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load lore')
    } finally {
      setIsLoading(false)
    }
  }

  const filteredEntities = entities.filter(entity => {
    const matchesSearch = entity.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         (entity.description?.toLowerCase().includes(searchQuery.toLowerCase()) ?? false)
    const matchesType = !selectedType || entity.type === selectedType
    return matchesSearch && matchesType
  })

  const entityTypes = [...new Set(entities.map(e => e.type))]

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-48">
        <Loader2 className="w-6 h-6 animate-spin text-gold" />
      </div>
    )
  }

  if (error) {
    return (
      <div className="p-4 text-center text-muted-foreground">
        <p>{error}</p>
        <button 
          onClick={loadEntities}
          className="mt-2 text-gold hover:underline"
        >
          Try again
        </button>
      </div>
    )
  }

  // Entity Detail View
  if (selectedEntity) {
    const config = ENTITY_TYPE_CONFIG[selectedEntity.type] || ENTITY_TYPE_CONFIG.concept
    const Icon = config.icon

    return (
      <div className="p-4 space-y-4">
        <button
          onClick={() => setSelectedEntity(null)}
          className="flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground"
        >
          <ChevronRight className="w-4 h-4 rotate-180" />
          Back to list
        </button>

        <div className="space-y-3">
          <div className="flex items-start gap-3">
            <div className={cn('p-2 rounded-lg bg-charcoal-700', config.color)}>
              <Icon className="w-5 h-5" />
            </div>
            <div>
              <h3 className="font-serif text-lg text-foreground">{selectedEntity.name}</h3>
              <Badge variant="outline" className="text-xs">
                {config.label}
              </Badge>
            </div>
          </div>

          <p className="text-sm text-muted-foreground leading-relaxed">
            {selectedEntity.description || 'No description available.'}
          </p>

          <button
            onClick={() => {
              // Copy entity name to clipboard for easy reference
              navigator.clipboard.writeText(selectedEntity.name)
            }}
            className="w-full py-2 px-3 rounded-md bg-gold/10 text-gold text-sm 
                       hover:bg-gold/20 transition-colors"
          >
            Copy name to clipboard
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full">
      {/* Search */}
      <div className="p-3 border-b border-charcoal-700">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Search lore..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-9 bg-charcoal-800 border-charcoal-700"
          />
        </div>
      </div>

      {/* Type Filters */}
      <div className="p-3 border-b border-charcoal-700">
        <div className="flex flex-wrap gap-1.5">
          <button
            onClick={() => setSelectedType(null)}
            className={cn(
              'px-2 py-1 rounded text-xs transition-colors',
              !selectedType
                ? 'bg-gold/20 text-gold'
                : 'bg-charcoal-700 text-muted-foreground hover:text-foreground'
            )}
          >
            All
          </button>
          {entityTypes.map(type => {
            const config = ENTITY_TYPE_CONFIG[type]
            return (
              <button
                key={type}
                onClick={() => setSelectedType(type)}
                className={cn(
                  'px-2 py-1 rounded text-xs transition-colors',
                  selectedType === type
                    ? 'bg-gold/20 text-gold'
                    : 'bg-charcoal-700 text-muted-foreground hover:text-foreground'
                )}
              >
                {config?.label || type}
              </button>
            )
          })}
        </div>
      </div>

      {/* Entity List */}
      <div className="flex-1 overflow-auto">
        {filteredEntities.length === 0 ? (
          <div className="p-4 text-center text-muted-foreground text-sm">
            No entities found
          </div>
        ) : (
          <div className="divide-y divide-charcoal-700">
            {filteredEntities.map(entity => {
              const config = ENTITY_TYPE_CONFIG[entity.type] || ENTITY_TYPE_CONFIG.concept
              const Icon = config.icon

              return (
                <button
                  key={entity.id}
                  onClick={() => setSelectedEntity(entity)}
                  className="w-full p-3 text-left hover:bg-charcoal-700/50 transition-colors"
                >
                  <div className="flex items-start gap-2">
                    <Icon className={cn('w-4 h-4 mt-0.5 shrink-0', config.color)} />
                    <div className="min-w-0">
                      <p className="font-medium text-foreground truncate">{entity.name}</p>
                      <p className="text-xs text-muted-foreground line-clamp-2">
                        {entity.description || 'No description'}
                      </p>
                    </div>
                  </div>
                </button>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

