'use client'

import { useState, useEffect, useRef } from 'react'
import { Dices } from 'lucide-react'

/**
 * Visual Dice Roller
 * 
 * Animated dice results with physics-style tumbling effect.
 * Shows individual dice + total with critical hit/fail indicators.
 */

interface DiceResult {
  formula: string
  results: number[]
  modifier: number
  total: number
  isCriticalHit: boolean
  isCriticalFail: boolean
  rollType?: string
  rollerName?: string
  timestamp: number
}

interface Props {
  results: DiceResult[]
  maxVisible?: number
}

export function DiceRollVisualizer({ results, maxVisible = 5 }: Props) {
  const [animatingId, setAnimatingId] = useState<number | null>(null)
  const containerRef = useRef<HTMLDivElement>(null)

  // Animate the latest roll
  useEffect(() => {
    if (results.length > 0) {
      const latest = results[results.length - 1]
      setAnimatingId(latest.timestamp)
      const timer = setTimeout(() => setAnimatingId(null), 1200)
      return () => clearTimeout(timer)
    }
  }, [results])

  // Auto-scroll to latest
  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight
    }
  }, [results])

  const visibleResults = results.slice(-maxVisible)

  return (
    <div ref={containerRef} className="space-y-2 max-h-64 overflow-y-auto scrollbar-thin">
      {visibleResults.map((roll) => (
        <DiceRollResult
          key={roll.timestamp}
          roll={roll}
          isAnimating={animatingId === roll.timestamp}
        />
      ))}
    </div>
  )
}

function DiceRollResult({ roll, isAnimating }: { roll: DiceResult; isAnimating: boolean }) {
  return (
    <div
      className={`rounded-lg p-3 transition-all duration-300 ${
        roll.isCriticalHit
          ? 'bg-amber-500/20 border border-amber-500/40 shadow-lg shadow-amber-500/10'
          : roll.isCriticalFail
          ? 'bg-red-500/20 border border-red-500/40 shadow-lg shadow-red-500/10'
          : 'bg-teal-rich/40 border border-gold/10'
      } ${isAnimating ? 'animate-bounce-once scale-105' : ''}`}
    >
      {/* Header */}
      <div className="flex items-center justify-between mb-1">
        <div className="flex items-center gap-2">
          <Dices className="w-3.5 h-3.5 text-gold" />
          {roll.rollerName && (
            <span className="text-xs text-parchment font-medium">{roll.rollerName}</span>
          )}
          <span className="text-xs text-parchment-muted">{roll.formula}</span>
          {roll.rollType && roll.rollType !== 'custom' && (
            <span className="text-xs text-parchment-muted/60 capitalize">
              ({roll.rollType.replace('_', ' ')})
            </span>
          )}
        </div>
        <div className={`text-lg font-bold font-mono ${
          roll.isCriticalHit ? 'text-amber-400' : roll.isCriticalFail ? 'text-red-400' : 'text-gold'
        }`}>
          {roll.total}
        </div>
      </div>

      {/* Dice Display */}
      <div className="flex items-center gap-1.5 flex-wrap">
        {roll.results.map((die, i) => (
          <DiceFace
            key={i}
            value={die}
            isCrit={roll.results.length === 1 && roll.isCriticalHit}
            isFail={roll.results.length === 1 && roll.isCriticalFail}
            isAnimating={isAnimating}
            delay={i * 100}
          />
        ))}
        {roll.modifier !== 0 && (
          <span className="text-xs text-parchment-muted ml-1">
            {roll.modifier > 0 ? `+${roll.modifier}` : roll.modifier}
          </span>
        )}
      </div>

      {/* Critical Indicator */}
      {roll.isCriticalHit && (
        <div className="text-xs text-amber-400 mt-1 font-bold uppercase tracking-wider animate-pulse">
          Critical Hit!
        </div>
      )}
      {roll.isCriticalFail && (
        <div className="text-xs text-red-400 mt-1 font-bold uppercase tracking-wider">
          Critical Fail!
        </div>
      )}
    </div>
  )
}

function DiceFace({ value, isCrit, isFail, isAnimating, delay }: {
  value: number
  isCrit: boolean
  isFail: boolean
  isAnimating: boolean
  delay: number
}) {
  const [showValue, setShowValue] = useState(!isAnimating)
  const [tumbleValue, setTumbleValue] = useState(Math.ceil(Math.random() * 20))

  useEffect(() => {
    if (isAnimating) {
      setShowValue(false)
      // Tumble through random values
      const interval = setInterval(() => {
        setTumbleValue(Math.ceil(Math.random() * 20))
      }, 50)

      const timer = setTimeout(() => {
        clearInterval(interval)
        setShowValue(true)
      }, 600 + delay)

      return () => {
        clearInterval(interval)
        clearTimeout(timer)
      }
    } else {
      setShowValue(true)
    }
  }, [isAnimating, value, delay])

  const displayValue = showValue ? value : tumbleValue

  return (
    <div
      className={`w-8 h-8 rounded-md flex items-center justify-center text-sm font-bold font-mono transition-all ${
        isAnimating && !showValue ? 'animate-spin-fast' : ''
      } ${
        isCrit
          ? 'bg-amber-500/30 text-amber-300 border border-amber-500/50 shadow-xs shadow-amber-500/20'
          : isFail
          ? 'bg-red-500/30 text-red-300 border border-red-500/50'
          : 'bg-teal-rich/80 text-parchment border border-gold/20'
      }`}
      style={{ animationDelay: `${delay}ms` }}
    >
      {displayValue}
    </div>
  )
}

/**
 * Quick Dice Buttons — reusable row of common dice
 */
export function QuickDiceButtons({ onRoll }: { onRoll: (formula: string) => void }) {
  const dice = [
    { formula: '1d4', label: 'd4', color: 'text-blue-400' },
    { formula: '1d6', label: 'd6', color: 'text-green-400' },
    { formula: '1d8', label: 'd8', color: 'text-purple-400' },
    { formula: '1d10', label: 'd10', color: 'text-orange-400' },
    { formula: '1d12', label: 'd12', color: 'text-pink-400' },
    { formula: '1d20', label: 'd20', color: 'text-gold' },
    { formula: '1d100', label: 'd100', color: 'text-red-400' },
  ]

  return (
    <div className="flex gap-1.5 flex-wrap">
      {dice.map(d => (
        <button
          key={d.formula}
          onClick={() => onRoll(d.formula)}
          className={`px-2.5 py-1.5 rounded-md text-xs font-bold border border-gold/10 bg-teal-rich/50 hover:bg-teal-rich/80 hover:border-gold/30 transition-all ${d.color}`}
        >
          {d.label}
        </button>
      ))}
    </div>
  )
}

/**
 * Parse a dice formula and roll it client-side (for preview / local rolls)
 */
export function rollDiceLocally(formula: string): { results: number[]; modifier: number; total: number } {
  const match = formula.match(/^(\d+)d(\d+)([+-]\d+)?$/)
  if (!match) return { results: [0], modifier: 0, total: 0 }

  const count = parseInt(match[1])
  const sides = parseInt(match[2])
  const modifier = match[3] ? parseInt(match[3]) : 0

  const results: number[] = []
  for (let i = 0; i < count; i++) {
    results.push(Math.floor(Math.random() * sides) + 1)
  }

  const total = results.reduce((a, b) => a + b, 0) + modifier
  return { results, modifier, total }
}

'use client'

import { confirmDialog } from '@/components/ui/confirm-dialog'
import { toast } from '@/components/ui/sonner'
/**
 * MapsVTT — minimal in-browser VTT for a quest scene.
 *
 * Features (MVP):
 *  - Scene map image background (uses scene.map_url or scene.image_url)
 *  - Toggleable square grid overlay
 *  - Draggable tokens (PCs + monsters) with HP/AC labels
 *  - Measurement tool: click two points → distance in 5ft squares
 *  - Fog-of-war "reveal" brush (circles)
 *
 * Persistence: state saved to quest_scenes.metadata.vtt via server action.
 * No new tables, no migrations.
 */

import { useEffect, useRef, useState, useCallback } from 'react'
import { Button } from '@/components/ui/button'
import { Grid3x3, Ruler, Cloud, Eraser, Plus, Save, Trash2 } from 'lucide-react'
import { saveVttState, type VttState, type VttToken } from '@/lib/actions/vtt'

interface Props {
  sceneId: string
  bgUrl: string | null
  initialState?: Partial<VttState> | null
  isDM: boolean
}

type Tool = 'select' | 'measure' | 'reveal' | 'add-token'

function defaultState(bgUrl: string | null): VttState {
  return {
    tokens: [],
    gridSize: 50,
    showGrid: true,
    fog: [],
    revealed: [],
    bgUrl,
  }
}

export function MapsVTT({ sceneId, bgUrl, initialState, isDM }: Props) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const bgImageRef = useRef<HTMLImageElement | null>(null)
  const [state, setState] = useState<VttState>(() => ({ ...defaultState(bgUrl), ...(initialState ?? {}) }))
  const [tool, setTool] = useState<Tool>('select')
  const [draggingId, setDraggingId] = useState<string | null>(null)
  const [measure, setMeasure] = useState<{ x1: number; y1: number; x2?: number; y2?: number } | null>(null)
  const [dirty, setDirty] = useState(false)
  const [saving, setSaving] = useState(false)

  // Load background image.
  useEffect(() => {
    const url = state.bgUrl
    if (!url) {
      bgImageRef.current = null
      draw()
      return
    }
    const img = new Image()
    img.crossOrigin = 'anonymous'
    img.onload = () => {
      bgImageRef.current = img
      draw()
    }
    img.src = url
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state.bgUrl])

  // Redraw on state change.
  useEffect(() => {
    draw()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state, measure])

  const draw = useCallback(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    const { width, height } = canvas

    ctx.clearRect(0, 0, width, height)
    ctx.fillStyle = '#0c1416'
    ctx.fillRect(0, 0, width, height)

    if (bgImageRef.current) {
      const img = bgImageRef.current
      const scale = Math.min(width / img.width, height / img.height)
      const dw = img.width * scale
      const dh = img.height * scale
      const dx = (width - dw) / 2
      const dy = (height - dh) / 2
      ctx.drawImage(img, dx, dy, dw, dh)
    }

    // Grid
    if (state.showGrid) {
      ctx.strokeStyle = 'rgba(212, 168, 75, 0.18)'
      ctx.lineWidth = 1
      for (let x = 0; x <= width; x += state.gridSize) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, height); ctx.stroke()
      }
      for (let y = 0; y <= height; y += state.gridSize) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(width, y); ctx.stroke()
      }
    }

    // Fog reveals (cut holes in dark overlay)
    if (state.fog.length > 0) {
      ctx.save()
      ctx.fillStyle = 'rgba(8, 10, 12, 0.7)'
      ctx.fillRect(0, 0, width, height)
      ctx.globalCompositeOperation = 'destination-out'
      for (const f of state.fog) {
        ctx.beginPath()
        ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2)
        ctx.fill()
      }
      ctx.restore()
    }

    // Tokens
    for (const t of state.tokens) {
      ctx.save()
      ctx.beginPath()
      ctx.arc(t.x, t.y, t.size, 0, Math.PI * 2)
      ctx.fillStyle = t.color
      ctx.globalAlpha = 0.85
      ctx.fill()
      ctx.globalAlpha = 1
      ctx.lineWidth = 2
      ctx.strokeStyle = t.isPC ? '#5eead4' : '#fda4af'
      ctx.stroke()
      ctx.fillStyle = '#fff'
      ctx.font = 'bold 11px Georgia, serif'
      ctx.textAlign = 'center'
      ctx.fillText(t.label.slice(0, 8), t.x, t.y + 3)
      if (t.hp != null && t.maxHp) {
        const pct = Math.max(0, Math.min(1, t.hp / t.maxHp))
        ctx.fillStyle = 'rgba(0,0,0,0.6)'
        ctx.fillRect(t.x - t.size, t.y + t.size + 2, t.size * 2, 4)
        ctx.fillStyle = pct > 0.5 ? '#10b981' : pct > 0.25 ? '#f59e0b' : '#ef4444'
        ctx.fillRect(t.x - t.size, t.y + t.size + 2, t.size * 2 * pct, 4)
      }
      ctx.restore()
    }

    // Measurement
    if (measure && measure.x2 != null && measure.y2 != null) {
      ctx.save()
      ctx.strokeStyle = '#fbbf24'
      ctx.lineWidth = 2
      ctx.setLineDash([6, 4])
      ctx.beginPath()
      ctx.moveTo(measure.x1, measure.y1)
      ctx.lineTo(measure.x2, measure.y2)
      ctx.stroke()
      const dx = measure.x2 - measure.x1
      const dy = measure.y2 - measure.y1
      const squares = Math.round(Math.sqrt(dx * dx + dy * dy) / state.gridSize)
      ctx.setLineDash([])
      ctx.fillStyle = '#fbbf24'
      ctx.font = 'bold 12px Georgia, serif'
      ctx.fillText(`${squares * 5} ft`, (measure.x1 + measure.x2) / 2, (measure.y1 + measure.y2) / 2 - 8)
      ctx.restore()
    }
  }, [state, measure])

  // Resize canvas to container.
  useEffect(() => {
    function resize() {
      const c = canvasRef.current
      const wrap = containerRef.current
      if (!c || !wrap) return
      const w = wrap.clientWidth
      const h = Math.min(700, Math.max(400, w * 0.6))
      c.width = w
      c.height = h
      draw()
    }
    resize()
    window.addEventListener('resize', resize)
    return () => window.removeEventListener('resize', resize)
  }, [draw])

  function hit(x: number, y: number): VttToken | null {
    for (let i = state.tokens.length - 1; i >= 0; i--) {
      const t = state.tokens[i]
      const dx = x - t.x
      const dy = y - t.y
      if (dx * dx + dy * dy <= t.size * t.size) return t
    }
    return null
  }

  async function onPointerDown(e: React.PointerEvent<HTMLCanvasElement>) {
    if (!isDM) return
    const rect = canvasRef.current!.getBoundingClientRect()
    const x = e.clientX - rect.left
    const y = e.clientY - rect.top

    if (tool === 'measure') {
      setMeasure({ x1: x, y1: y })
      return
    }
    if (tool === 'reveal') {
      setState((s) => ({ ...s, fog: [...s.fog, { x, y, r: 80 }] }))
      setDirty(true)
      return
    }
    if (tool === 'add-token') {
      const isPC = await confirmDialog({ title: 'Add token', description: 'Is this token a player character or a monster?', confirmLabel: 'Player character', cancelLabel: 'Monster' })
      const label = prompt('Token label?') ?? 'New'
      const token: VttToken = {
        id: crypto.randomUUID(),
        label,
        color: isPC ? '#0e7490' : '#7f1d1d',
        x, y,
        size: state.gridSize / 2 - 4,
        isPC,
        hp: 10,
        maxHp: 10,
      }
      setState((s) => ({ ...s, tokens: [...s.tokens, token] }))
      setDirty(true)
      setTool('select')
      return
    }

    const t = hit(x, y)
    if (t) setDraggingId(t.id)
  }

  function onPointerMove(e: React.PointerEvent<HTMLCanvasElement>) {
    const rect = canvasRef.current!.getBoundingClientRect()
    const x = e.clientX - rect.left
    const y = e.clientY - rect.top
    if (measure && measure.x2 == null) {
      setMeasure({ ...measure, x2: x, y2: y })
    } else if (measure && tool === 'measure') {
      setMeasure({ ...measure, x2: x, y2: y })
    }
    if (draggingId) {
      // Snap to grid.
      const g = state.gridSize
      const snapped = { x: Math.round(x / g) * g + g / 2, y: Math.round(y / g) * g + g / 2 }
      setState((s) => ({
        ...s,
        tokens: s.tokens.map((t) => (t.id === draggingId ? { ...t, x: snapped.x, y: snapped.y } : t)),
      }))
      setDirty(true)
    }
  }

  function onPointerUp() {
    setDraggingId(null)
    if (tool === 'measure' && measure) {
      // Keep last measurement visible briefly, then clear.
      setTimeout(() => setMeasure(null), 1500)
    }
  }

  async function save() {
    setSaving(true)
    try {
      await saveVttState(sceneId, state)
      setDirty(false)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Save failed')
    } finally {
      setSaving(false)
    }
  }

  async function clearFog() {
    if (!(await confirmDialog({ description: 'Reset fog of war (re-cover the map)?', destructive: true }))) return
    setState((s) => ({ ...s, fog: [] }))
    setDirty(true)
  }

  function removeSelectedToken() {
    if (!draggingId) {
      const label = prompt('Token label to remove?')
      if (!label) return
      setState((s) => ({ ...s, tokens: s.tokens.filter((t) => t.label !== label) }))
    } else {
      setState((s) => ({ ...s, tokens: s.tokens.filter((t) => t.id !== draggingId) }))
    }
    setDirty(true)
  }

  return (
    <div className="space-y-2" ref={containerRef}>
      {isDM && (
        <div className="flex items-center gap-1 flex-wrap p-2 bg-charcoal-900/60 rounded border border-gold/10">
          <ToolBtn label="Select" active={tool === 'select'} onClick={() => setTool('select')} />
          <ToolBtn icon={<Plus className="w-3.5 h-3.5" />} label="Token" active={tool === 'add-token'} onClick={() => setTool('add-token')} />
          <ToolBtn icon={<Ruler className="w-3.5 h-3.5" />} label="Measure" active={tool === 'measure'} onClick={() => setTool('measure')} />
          <ToolBtn icon={<Cloud className="w-3.5 h-3.5" />} label="Reveal Fog" active={tool === 'reveal'} onClick={() => setTool('reveal')} />
          <div className="w-px h-5 bg-gold/15 mx-1" />
          <ToolBtn
            icon={<Grid3x3 className="w-3.5 h-3.5" />}
            label={state.showGrid ? 'Hide Grid' : 'Show Grid'}
            onClick={() => { setState((s) => ({ ...s, showGrid: !s.showGrid })); setDirty(true) }}
          />
          <ToolBtn icon={<Eraser className="w-3.5 h-3.5" />} label="Clear Fog" onClick={clearFog} />
          <ToolBtn icon={<Trash2 className="w-3.5 h-3.5" />} label="Remove Token" onClick={removeSelectedToken} />
          <div className="ml-auto flex items-center gap-2">
            {dirty && <span className="text-xs text-amber-300">unsaved</span>}
            <Button size="sm" onClick={save} disabled={!dirty || saving} className="text-xs">
              <Save className="w-3 h-3 mr-1" /> {saving ? 'Saving…' : 'Save'}
            </Button>
          </div>
        </div>
      )}
      <canvas
        ref={canvasRef}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        className="block w-full rounded border border-gold/10 cursor-crosshair touch-none"
      />
    </div>
  )
}

function ToolBtn({ icon, label, active, onClick }: { icon?: React.ReactNode; label: string; active?: boolean; onClick: () => void }) {
  return (
    <button
      onClick={onClick}
      className={`flex items-center gap-1 px-2.5 py-1 rounded text-xs transition-colors ${
        active ? 'bg-gold/20 text-gold' : 'text-parchment-muted hover:text-parchment hover:bg-charcoal-800'
      }`}
    >
      {icon} {label}
    </button>
  )
}

