  | 'climax'

export interface QuestSummary {
  id: string
  slug: string
  title: string
  quest_type?: string | null
  difficulty?: string | null
  status?: string | null
}

export type QuestNodeData = {
  kind: QuestNodeKind
  label: string
  description?: string
  // Type-specific fields
  monsters?: string
  npc_name?: string
  reward?: string
  outcomes?: string
