export function SafetySummaryCard({ questId, totalPlayers }: Props) {
  const [summary, setSummary] = useState<Summary | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [expanded, setExpanded] = useState(true)

  async function load() {
    setLoading(true)
    setError(null)
    const res = await getQuestSafetySummary(questId)
    if (res.success && res.data) {
      setSummary(res.data)
    } else {
      setError(res.error ?? 'Failed to load safety summary')
    }
    setLoading(false)
  }

  useEffect(() => {
    load()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [questId])

  const dominantTone =
    summary &&
    (Object.entries(summary.tones) as ['light' | 'mixed' | 'dark', number][])
      .sort((a, b) => b[1] - a[1])[0]

  return (
    <div className="rounded-lg border border-rose-400/20 bg-rose-950/10 p-3">
      <button
        type="button"
        onClick={() => setExpanded(e => !e)}
        className="w-full flex items-center justify-between gap-2 text-left"
      >
        <div className="flex items-center gap-2">
          <Shield className="w-4 h-4 text-rose-300" />
          <span className="text-sm font-serif text-parchment">Safety Summary</span>
        </div>
        <div className="flex items-center gap-2 text-[11px] text-parchment-muted">
          {summary && (
            <span>
              {summary.completed}/{totalPlayers} ready
            </span>
          )}
          <span className="text-gold/60">{expanded ? '−' : '+'}</span>
        </div>
      </button>

      {expanded && (
        <div className="mt-3 space-y-3">
          {loading && (
            <div className="flex items-center gap-2 text-xs text-parchment-muted">
              <Loader2 className="w-3 h-3 animate-spin" /> Loading…
            </div>
          )}

          {error && <p className="text-xs text-red-400">{error}</p>}

          {summary && !loading && (
            <>
              {summary.pending > 0 && (
                <div className="text-[11px] text-amber-300/90 bg-amber-950/20 border border-amber-400/20 rounded px-2 py-1">
                  {summary.pending} player{summary.pending === 1 ? '' : 's'} haven&apos;t completed Session Zero yet.
                </div>
              )}

              {dominantTone && dominantTone[1] > 0 && (
                <div className="text-[11px] text-parchment-muted">
                  Table tone leans{' '}
                  <span className="capitalize text-parchment font-medium">{dominantTone[0]}</span>
                  {' '}({summary.tones.light}L · {summary.tones.mixed}M · {summary.tones.dark}D)
                </div>
              )}

              <div>
                <div className="text-[10px] uppercase tracking-wider text-rose-300/80 mb-1 flex items-center gap-1">
                  <Shield className="w-3 h-3" /> Lines (hard noes)
                </div>
                {summary.lines.length === 0 ? (
                  <p className="text-xs text-parchment-muted/70 italic">None reported.</p>
                ) : (
                  <ul className="space-y-1">
                    {summary.lines.map((l, i) => (
                      <li key={i} className="text-xs text-parchment/90 bg-rose-950/20 border border-rose-400/15 rounded px-2 py-1">
                        {l}
                      </li>
                    ))}
                  </ul>
                )}
              </div>

              <div>
                <div className="text-[10px] uppercase tracking-wider text-amber-300/80 mb-1 flex items-center gap-1">
                  <EyeOff className="w-3 h-3" /> Veils (fade-to-black)
                </div>
                {summary.veils.length === 0 ? (
                  <p className="text-xs text-parchment-muted/70 italic">None reported.</p>
                ) : (
                  <ul className="space-y-1">
                    {summary.veils.map((v, i) => (
                      <li key={i} className="text-xs text-parchment/90 bg-amber-950/20 border border-amber-400/15 rounded px-2 py-1">
                        {v}
                      </li>
                    ))}
                  </ul>
                )}
              </div>

              <button
                type="button"
                onClick={load}
                className="text-[11px] text-parchment-muted hover:text-parchment inline-flex items-center gap-1"
              >
                <RefreshCw className="w-3 h-3" /> Refresh
              </button>
            </>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useTransition, useEffect } from 'react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Heart, Shield, EyeOff, Plus, X, Loader2 } from 'lucide-react'
import { submitSessionZero, getSessionZero } from '@/lib/actions/quests'
import type { TonePreference, HeartAnchor } from '@/types/quest'

interface Props {
  questId: string
  questTitle: string
  open: boolean
  onOpenChange: (open: boolean) => void
  onCompleted?: () => void
}

const TONE_OPTIONS: { value: TonePreference; label: string; description: string }[] = [
  { value: 'light',  label: 'Light',  description: 'Heroic, hopeful. Loss is rare and earned.' },
  { value: 'mixed',  label: 'Mixed',  description: 'Real stakes, balanced with humor and hope.' },
  { value: 'dark',   label: 'Dark',   description: 'Grim, costly. Tragedy is on the table.' },
]

const MAX_ANCHORS = 3

/**
 * Session Zero Modal — Safety floor + heart anchors.
 *
 * Establishes player-defined narrative boundaries (lines / veils),
 * a tone preference, and 1–3 "heart anchors" — what their character
 * cares about most. Saved per-player, surfaced to the DM dashboard.
 */
export function SessionZeroModal({ questId, questTitle, open, onOpenChange, onCompleted }: Props) {
  const [lines, setLines] = useState('')
  const [veils, setVeils] = useState('')
  const [tone, setTone] = useState<TonePreference>('mixed')
  const [anchors, setAnchors] = useState<HeartAnchor[]>([{ label: '' }])
  const [loadingExisting, setLoadingExisting] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [isPending, startTransition] = useTransition()

  // Load existing answers (if any) when modal opens
  useEffect(() => {
    if (!open) return
    let cancelled = false
    setLoadingExisting(true)
    setError(null)
    getSessionZero(questId).then((res) => {
      if (cancelled) return
      if (res.success && res.data) {
        setLines(res.data.lines_text || '')
        setVeils(res.data.veils_text || '')
        setTone((res.data.tone_preference as TonePreference) || 'mixed')
        const existing = res.data.heart_anchors
        setAnchors(existing.length > 0 ? existing : [{ label: '' }])
      }
      setLoadingExisting(false)
    })
    return () => { cancelled = true }
  }, [open, questId])

  const updateAnchor = (i: number, patch: Partial<HeartAnchor>) => {
    setAnchors(prev => prev.map((a, idx) => (idx === i ? { ...a, ...patch } : a)))
  }
  const addAnchor = () => {
    if (anchors.length >= MAX_ANCHORS) return
    setAnchors(prev => [...prev, { label: '' }])
  }
  const removeAnchor = (i: number) => {
    setAnchors(prev => prev.filter((_, idx) => idx !== i))
  }

  const handleSubmit = () => {
    const cleanedAnchors = anchors
      .map(a => ({ label: a.label.trim(), note: a.note?.trim() }))
      .filter(a => a.label.length > 0)

    setError(null)
    startTransition(async () => {
      const result = await submitSessionZero({
        questId,
        lines,
        veils,
        tonePreference: tone,
        heartAnchors: cleanedAnchors,
      })
      if (!result.success) {
        setError(result.error || 'Could not save your Session Zero.')
        return
      }
      onCompleted?.()
      onOpenChange(false)
    })
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto bg-slate-950 border-slate-800">
        <DialogHeader>
          <DialogTitle className="text-2xl font-serif text-slate-100">
            Session Zero
          </DialogTitle>
          <DialogDescription className="text-slate-400">
            Before we begin <span className="text-slate-200">{questTitle}</span>, set
            the floor of safety and tell the DM what your character holds dear. Private to you and the DM.
          </DialogDescription>
        </DialogHeader>

        {loadingExisting ? (
          <div className="flex items-center justify-center py-16">
            <Loader2 className="w-6 h-6 animate-spin text-slate-500" />
          </div>
        ) : (
          <div className="space-y-6 pt-2">
            {/* LINES */}
            <section>
              <label className="flex items-center gap-2 text-sm font-medium text-rose-300 mb-2">
                <Shield className="w-4 h-4" />
                Lines — never in our story
              </label>
              <textarea
                value={lines}
                onChange={(e) => setLines(e.target.value.slice(0, 1000))}
                rows={3}
                placeholder="Topics that must not appear at the table. E.g. harm to children, graphic torture, real-world hate."
                className="w-full bg-slate-900 border border-rose-900/40 rounded-md px-3 py-2 text-sm text-slate-200 placeholder:text-slate-600 focus:outline-hidden focus:ring-1 focus:ring-rose-500/40 resize-none"
              />
              <p className="text-[11px] text-slate-500 mt-1">
                Hard limit. The DM will keep these out of the quest. {lines.length}/1000
              </p>
            </section>

            {/* VEILS */}
            <section>
              <label className="flex items-center gap-2 text-sm font-medium text-amber-300 mb-2">
                <EyeOff className="w-4 h-4" />
                Veils — fade to black if they appear
              </label>
              <textarea
                value={veils}
                onChange={(e) => setVeils(e.target.value.slice(0, 1000))}
                rows={3}
                placeholder="Topics that may exist off-screen but should not be played out in detail."
                className="w-full bg-slate-900 border border-amber-900/40 rounded-md px-3 py-2 text-sm text-slate-200 placeholder:text-slate-600 focus:outline-hidden focus:ring-1 focus:ring-amber-500/40 resize-none"
              />
              <p className="text-[11px] text-slate-500 mt-1">
                Soft limit. The DM will narrate around these. {veils.length}/1000
              </p>
            </section>

            {/* TONE */}
            <section>
              <label className="block text-sm font-medium text-slate-300 mb-2">
                Tone preference
              </label>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                {TONE_OPTIONS.map((opt) => {
                  const selected = tone === opt.value
                  return (
                    <button
                      key={opt.value}
                      type="button"
                      onClick={() => setTone(opt.value)}
                      className={[
                        'text-left rounded-md border px-3 py-2 transition',
                        selected
                          ? 'border-indigo-400 bg-indigo-500/10'
                          : 'border-slate-800 bg-slate-900 hover:border-slate-700',
                      ].join(' ')}
                    >
                      <div className={selected ? 'text-indigo-200 font-medium' : 'text-slate-200 font-medium'}>
                        {opt.label}
                      </div>
                      <div className="text-[11px] text-slate-500 mt-0.5 leading-snug">
                        {opt.description}
                      </div>
                    </button>
                  )
                })}
              </div>
            </section>

            {/* HEART ANCHORS */}
            <section>
              <label className="flex items-center gap-2 text-sm font-medium text-pink-300 mb-2">
                <Heart className="w-4 h-4" />
                Heart anchors — what your character holds dear
              </label>
              <p className="text-[11px] text-slate-500 mb-3">
                Up to {MAX_ANCHORS}. The DM will see these and may weave them in. Examples: <span className="text-slate-400">&ldquo;My sister in Vale&rdquo;</span>, <span className="text-slate-400">&ldquo;The owl, Cob&rdquo;</span>, <span className="text-slate-400">&ldquo;Restoring my house&rsquo;s honor&rdquo;</span>.
              </p>
              <div className="space-y-2">
                {anchors.map((a, i) => (
                  <div key={i} className="flex gap-2 items-start">
                    <div className="flex-1 space-y-1">
                      <input
                        value={a.label}
                        onChange={(e) => updateAnchor(i, { label: e.target.value.slice(0, 80) })}
                        placeholder={`Anchor ${i + 1}`}
                        className="w-full bg-slate-900 border border-slate-800 rounded-md px-3 py-2 text-sm text-slate-200 placeholder:text-slate-600 focus:outline-hidden focus:ring-1 focus:ring-pink-500/40"
                      />
                      <input
                        value={a.note || ''}
                        onChange={(e) => updateAnchor(i, { note: e.target.value.slice(0, 200) })}
                        placeholder="Why it matters (optional)"
                        className="w-full bg-slate-900/60 border border-slate-800/60 rounded-md px-3 py-1.5 text-xs text-slate-300 placeholder:text-slate-600 focus:outline-hidden focus:ring-1 focus:ring-pink-500/30"
                      />
                    </div>
                    {anchors.length > 1 && (
                      <button
                        type="button"
                        onClick={() => removeAnchor(i)}
                        className="p-2 text-slate-500 hover:text-rose-400 transition"
                        aria-label="Remove anchor"
                      >
                        <X className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                ))}
                {anchors.length < MAX_ANCHORS && (
                  <button
                    type="button"
                    onClick={addAnchor}
                    className="flex items-center gap-1.5 text-xs text-slate-400 hover:text-slate-200 transition"
                  >
                    <Plus className="w-3.5 h-3.5" /> Add another anchor
                  </button>
                )}
              </div>
            </section>

            {error && (
              <div className="text-sm text-rose-300 bg-rose-950/30 border border-rose-900/40 rounded-md px-3 py-2">
                {error}
              </div>
            )}
          </div>
        )}

        <DialogFooter className="pt-2">
          <Button
            variant="ghost"
            onClick={() => onOpenChange(false)}
            disabled={isPending}
            className="text-slate-400"
          >
            Later
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={isPending || loadingExisting}
            className="bg-indigo-600 hover:bg-indigo-500 text-white"
          >
            {isPending ? (
              <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Saving</>
            ) : (
              'Confirm & enter the quest'
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { confirmDialog } from '@/components/ui/confirm-dialog'
import { useEffect, useState, useTransition } from 'react'
import { Plus, Eye, EyeOff, Trash2, ChevronRight, Loader2, Cog } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  listWorldCogs,
  createWorldCog,
  updateWorldCog,
  deleteWorldCog,
  advanceWorldCog,
} from '@/lib/actions/quests'
import type { WorldCog, CogTempo } from '@/types/quest'

const TEMPO_STYLES: Record<CogTempo, { label: string; color: string; bg: string }> = {
  crawl:   { label: 'Crawl',   color: 'text-slate-300',  bg: 'bg-slate-500/10 border-slate-400/30' },
  steady:  { label: 'Steady',  color: 'text-gold',       bg: 'bg-gold/10 border-gold/30' },
  rushing: { label: 'Rushing', color: 'text-orange-300', bg: 'bg-orange-500/10 border-orange-400/30' },
}

const TEMPO_ORDER: CogTempo[] = ['crawl', 'steady', 'rushing']

export function WorldCogsPanel({ questId }: { questId: string }) {
  const [cogs, setCogs] = useState<WorldCog[]>([])
  const [loading, setLoading] = useState(true)
  const [adding, setAdding] = useState(false)
  const [pending, startTransition] = useTransition()

  // new-cog form state
  const [faction, setFaction] = useState('')
  const [goal, setGoal] = useState('')
  const [tempo, setTempo] = useState<CogTempo>('steady')
  const [nextBeat, setNextBeat] = useState('')
  const [visible, setVisible] = useState(false)

  const load = async () => {
    setLoading(true)
    const res = await listWorldCogs(questId)
    if (res.success && res.data) setCogs(res.data as WorldCog[])
    setLoading(false)
  }

  useEffect(() => {
    load()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [questId])

  const resetForm = () => {
    setFaction(''); setGoal(''); setTempo('steady'); setNextBeat(''); setVisible(false); setAdding(false)
  }

  const handleCreate = () => {
    if (!faction.trim() || !goal.trim()) return
    startTransition(async () => {
      const res = await createWorldCog({
        quest_id: questId,
        faction,
        goal,
        tempo,
        next_beat: nextBeat || null,
        visible_to_players: visible,
      })
      if (res.success) {
        resetForm()
        load()
      }
    })
  }

  const handleToggleVisible = (cog: WorldCog) => {
    startTransition(async () => {
      const res = await updateWorldCog(cog.id, { visible_to_players: !cog.visible_to_players })
      if (res.success) {
        setCogs(prev => prev.map(c => c.id === cog.id ? { ...c, visible_to_players: !c.visible_to_players } : c))
      }
    })
  }

  const handleTempo = (cog: WorldCog, next: CogTempo) => {
    startTransition(async () => {
      const res = await updateWorldCog(cog.id, { tempo: next })
      if (res.success) {
        setCogs(prev => prev.map(c => c.id === cog.id ? { ...c, tempo: next } : c))
      }
    })
  }

  const handleAdvance = (cog: WorldCog) => {
    const newBeat = window.prompt(`Advance "${cog.faction}". What is the NEW next beat?`, '')
    startTransition(async () => {
      const res = await advanceWorldCog(cog.id, newBeat?.trim() || null)
      if (res.success) load()
    })
  }

  const handleDelete = async (cog: WorldCog) => {
    if (!(await confirmDialog({ description: `Delete the cog "${cog.faction}"? This cannot be undone.`, destructive: true }))) return
    startTransition(async () => {
      const res = await deleteWorldCog(cog.id)
      if (res.success) setCogs(prev => prev.filter(c => c.id !== cog.id))
    })
  }

  return (
    <div className="flex-1 flex flex-col p-4 gap-3 overflow-y-auto">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-serif text-parchment flex items-center gap-2">
          <Cog className="w-4 h-4 text-gold" /> World Cogs
        </h3>
        <button
          onClick={() => setAdding(v => !v)}
          className="text-xs text-gold hover:text-gold/80 flex items-center gap-1"
        >
          <Plus className="w-3 h-3" /> {adding ? 'Cancel' : 'New cog'}
        </button>
      </div>
      <p className="text-[11px] text-parchment-muted italic">
        Offscreen plots that turn whether players see them or not. Light a fuse, then advance the tempo.
      </p>

      {adding && (
        <div className="p-3 rounded-lg bg-teal-rich/40 border border-gold/20 space-y-2">
          <Input
            value={faction}
            onChange={e => setFaction(e.target.value)}
            placeholder="Faction / actor (e.g. The Hollow Choir)"
            className="bg-teal-deep/60 border-gold/20 text-parchment text-sm"
          />
          <Input
            value={goal}
            onChange={e => setGoal(e.target.value)}
            placeholder="Goal (e.g. seize the Drowned Shard)"
            className="bg-teal-deep/60 border-gold/20 text-parchment text-sm"
          />
          <Input
            value={nextBeat}
            onChange={e => setNextBeat(e.target.value)}
            placeholder="Next beat (optional)"
            className="bg-teal-deep/60 border-gold/20 text-parchment text-sm"
          />
          <div className="flex flex-wrap items-center gap-1">
            <span className="text-[10px] uppercase tracking-wider text-parchment-muted mr-1">Tempo</span>
            {TEMPO_ORDER.map(t => (
              <button
                key={t}
                onClick={() => setTempo(t)}
                className={`text-[10px] px-2 py-0.5 rounded border transition-all ${
                  tempo === t ? `${TEMPO_STYLES[t].bg} ${TEMPO_STYLES[t].color}` : 'border-gold/10 text-parchment-muted hover:border-gold/30'
                }`}
              >
                {TEMPO_STYLES[t].label}
              </button>
            ))}
            <label className="flex items-center gap-1 ml-auto text-[11px] text-parchment-muted cursor-pointer">
              <input type="checkbox" checked={visible} onChange={e => setVisible(e.target.checked)} className="accent-gold" />
              Visible to players
            </label>
          </div>
          <Button
            onClick={handleCreate}
            disabled={pending || !faction.trim() || !goal.trim()}
            className="w-full btn-fantasy text-xs"
          >
            {pending ? <Loader2 className="w-3 h-3 animate-spin" /> : 'Create cog'}
          </Button>
        </div>
      )}

      {loading && (
        <div className="text-xs text-parchment-muted flex items-center gap-2">
          <Loader2 className="w-3 h-3 animate-spin" /> Loading cogs...
        </div>
      )}

      {!loading && cogs.length === 0 && !adding && (
        <div className="text-xs text-parchment-muted italic">
          No cogs yet. Add a faction, give them a goal, and the world starts breathing.
        </div>
      )}

      {cogs.map(cog => {
        const tempoStyle = TEMPO_STYLES[cog.tempo]
        return (
          <div
            key={cog.id}
            className={`p-3 rounded-lg border ${tempoStyle.bg} relative group`}
          >
            <div className="flex items-start justify-between gap-2 mb-1">
              <div className="flex-1 min-w-0">
                <div className="text-sm text-parchment font-medium truncate">{cog.faction}</div>
                <div className="text-xs text-parchment-muted italic line-clamp-2">{cog.goal}</div>
              </div>
              <button
                onClick={() => handleToggleVisible(cog)}
                title={cog.visible_to_players ? 'Visible to players — click to hide' : 'Hidden — click to reveal to players'}
                className={`shrink-0 ${cog.visible_to_players ? 'text-gold' : 'text-parchment-muted hover:text-parchment'}`}
              >
                {cog.visible_to_players ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
              </button>
            </div>

            {cog.current_state && (
              <div className="mt-1 text-[11px] text-parchment-dark">
                <span className="text-parchment-muted">Now:</span> {cog.current_state}
              </div>
            )}
            {cog.next_beat && (
              <div className="mt-0.5 text-[11px] text-parchment-dark">
                <span className="text-parchment-muted">Next:</span> {cog.next_beat}
              </div>
            )}

            <div className="flex items-center gap-1 mt-2 flex-wrap">
              <span className="text-[10px] uppercase tracking-wider text-parchment-muted mr-1">Tempo</span>
              {TEMPO_ORDER.map(t => (
                <button
                  key={t}
                  onClick={() => handleTempo(cog, t)}
                  disabled={pending}
                  className={`text-[10px] px-1.5 py-0.5 rounded border transition-all ${
                    cog.tempo === t
                      ? `${TEMPO_STYLES[t].bg} ${TEMPO_STYLES[t].color}`
                      : 'border-gold/10 text-parchment-muted hover:border-gold/30'
                  }`}
                >
                  {TEMPO_STYLES[t].label}
                </button>
              ))}
              <button
                onClick={() => handleAdvance(cog)}
                disabled={pending}
                className="ml-auto text-[10px] text-gold hover:text-gold/80 flex items-center gap-1"
                title="Promote Next → Now, set a new Next"
              >
                <ChevronRight className="w-3 h-3" /> Advance
              </button>
              <button
                onClick={() => handleDelete(cog)}
                disabled={pending}
                className="text-[10px] text-rose-400/70 hover:text-rose-300"
                title="Delete cog"
              >
                <Trash2 className="w-3 h-3" />
              </button>
            </div>
          </div>
        )
      })}
    </div>
  )
}
